const allModules=['Dashboard','Approvals','POS','Orders','Products','Inventory','Customers','Suppliers','Purchasing','Expenses','Cash Drawer','Reports','Staff','Branches','Restaurant','Pharmacy','Production','Payroll & HR','Route Sales','Audit Logs','Settings','SaaS Admin'];
const mapName={purchasing:'Purchasing',restaurant:'Restaurant',pharmacy:'Pharmacy',payroll:'Payroll & HR',production:'Production',route_sales:'Route Sales',reports:'Reports',pos:'POS',products:'Products',customers:'Customers',expenses:'Expenses'};
let token=localStorage.getItem('pos_token')||'',user=null,cart=[],enabledModules=[];
const $=id=>document.getElementById(id),money=v=>'UGX '+Number(v||0).toLocaleString(),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
async function api(path,opts={}){const r=await fetch('/api'+path,{...opts,headers:{'Content-Type':'application/json','Authorization':'Bearer '+token,...(opts.headers||{})}});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Request failed');return j}
function showRegister(){$('loginPane').classList.add('hidden');$('registerPane').classList.remove('hidden')}function showLogin(){$('registerPane').classList.add('hidden');$('loginPane').classList.remove('hidden')}
async function register(){try{const j=await api('/register',{method:'POST',body:JSON.stringify({name:$('rname').value,businessName:$('rbiz').value,email:$('remail').value,password:$('rpass').value,country:$('rcountry').value,currency:$('rcountry').value==='Uganda'?'UGX':$('rcountry').value==='Kenya'?'KES':$('rcountry').value==='Ghana'?'GHS':$('rcountry').value==='Nigeria'?'NGN':'RWF'})});token=j.token;user={...j.user,businessId:j.business.id};localStorage.setItem('pos_token',token);showApp()}catch(e){$('registerMsg').textContent=e.message;$('registerMsg').className='bad'}}
async function login(){try{const j=await api('/login',{method:'POST',body:JSON.stringify({email:$('email').value,password:$('password').value})});token=j.token;user=j.user;localStorage.setItem('pos_token',token);showApp()}catch(e){$('loginMsg').textContent=e.message;$('loginMsg').className='bad'}}
function logout(){localStorage.removeItem('pos_token');location.reload()}
async function showApp(){$('login').classList.add('hidden');$('app').classList.remove('hidden');if(!user)user=await api('/me');$('who').textContent=(user?.name||'User')+' · '+(user?.role||'');await loadModules();renderNav();openModule(user.role==='saas_admin'?'SaaS Admin':'Dashboard')}
async function loadModules(){if(user.role==='saas_admin'){enabledModules=allModules;return}const rows=await api('/modules');enabledModules=['Dashboard','Approvals','Orders','Inventory','Suppliers','Cash Drawer','Staff','Branches','Audit Logs','Settings'];rows.filter(x=>x.enabled&&x.active&&(x.core||!x.expires_at||new Date(x.expires_at)>new Date())).forEach(x=>{const n=mapName[x.code];if(n&&!enabledModules.includes(n))enabledModules.push(n)})}
function renderNav(){if(user.role==='saas_admin'){$('nav').innerHTML='<div class="nav-section">Platform Administration</div>'+['SaaS Admin'].map(m=>'<button data-m="'+m+'" onclick="openModule(\''+m+'\')">'+m+'</button>').join('');return}const allowed=m=>enabledModules.includes(m);const ops=['Dashboard','POS','Orders','Restaurant','Customers'].filter(allowed),admin=['Approvals','Products','Inventory','Suppliers','Purchasing','Expenses','Cash Drawer','Reports','Staff','Branches','Audit Logs','Settings'].filter(allowed);$('nav').innerHTML='<div class="nav-section">Restaurant Operations</div>'+ops.map(m=>'<button data-m="'+m+'" onclick="openModule(\''+m+'\')">'+m+'</button>').join('')+'<div class="nav-section admin-section">Administration</div>'+admin.map(m=>'<button data-m="'+m+'" onclick="openModule(\''+m+'\')">'+m+'</button>').join('')}
function setActive(m){document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.m===m));$('title').textContent=m}
function card(label,value,sub='',tone=''){return `<div class="kpi ${tone}"><span>${label}</span><strong>${value}</strong><small>${sub}</small></div>`}


function showToast(message,type='success'){let box=document.getElementById('appToast');if(!box){box=document.createElement('div');box.id='appToast';box.className='app-toast';document.body.appendChild(box)}box.textContent=message;box.className='app-toast '+type+' show';clearTimeout(window._toastTimer);window._toastTimer=setTimeout(()=>box.classList.remove('show'),2800)}
function appPrompt({title='Add note',message='',placeholder='Write a note...',required=false,urgent=false,confirmText='Continue',danger=false}={}){return new Promise(resolve=>{const overlay=document.createElement('div');overlay.className='app-modal-overlay';overlay.innerHTML='<div class="app-modal"><div class="app-modal-head"><div><h3>'+esc(title)+'</h3>'+(message?'<p>'+esc(message)+'</p>':'')+'</div><button class="app-modal-x" type="button" aria-label="Close">×</button></div><div class="app-modal-body"><label class="modal-label">Note<textarea id="modalNote" placeholder="'+esc(placeholder)+'"></textarea></label>'+(urgent?'<label class="urgent-toggle"><input id="modalUrgent" type="checkbox"><span><b>Mark as urgent</b><small>Moves this request to the top of the approval queue.</small></span></label>':'')+'</div><div class="app-modal-actions"><button class="secondary modal-cancel" type="button">Cancel</button><button class="'+(danger?'danger':'')+' modal-confirm" type="button">'+esc(confirmText)+'</button></div></div>';document.body.appendChild(overlay);const note=overlay.querySelector('#modalNote'),urgentBox=overlay.querySelector('#modalUrgent');const close=v=>{overlay.remove();resolve(v)};overlay.querySelector('.app-modal-x').onclick=()=>close(null);overlay.querySelector('.modal-cancel').onclick=()=>close(null);overlay.addEventListener('click',e=>{if(e.target===overlay)close(null)});overlay.querySelector('.modal-confirm').onclick=()=>{const val=note.value.trim();if(required&&!val){note.classList.add('field-error');note.focus();return}close({comment:val,urgent:!!urgentBox?.checked})};setTimeout(()=>note.focus(),20)})}

function bindPdfLinks(){document.querySelectorAll('[data-pdf]').forEach(btn=>btn.addEventListener('click',()=>openPdf(btn.dataset.pdf).catch(e=>alert(e.message))))}
async function openPdf(path){const r=await fetch('/api'+path,{headers:{'Authorization':'Bearer '+token}});if(!r.ok){const j=await r.json().catch(()=>({}));throw new Error(j.error||'Unable to generate PDF')}const blob=await r.blob(),url=URL.createObjectURL(blob);window.open(url,'_blank');setTimeout(()=>URL.revokeObjectURL(url),120000)}
async function getDocSettings(){return api('/document-settings')}
function previewDocument(title,number,meta,lines,total,currency='UGX'){const w=window.open('','_blank','width=900,height=900');const rows=lines.map(x=>'<tr><td>'+esc(x.name)+'</td><td class="right">'+esc(x.qty??'')+'</td><td class="right">'+esc(x.unit??'')+'</td><td class="right">'+esc(x.total??'')+'</td></tr>').join('');w.document.write('<!doctype html><html><head><title>'+esc(title)+'</title><style>body{font-family:Arial,sans-serif;margin:36px;color:#111}.head{display:flex;justify-content:space-between;border-bottom:2px solid #111;padding-bottom:14px;margin-bottom:20px}.head h1{margin:0;font-size:20px}.doc{text-align:right}.meta{display:grid;gap:5px;margin:18px 0}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{padding:9px;border-bottom:1px solid #ddd;text-align:left}.right{text-align:right}.total{text-align:right;font-size:20px;font-weight:700;margin-top:20px}.note{margin-top:26px;color:#666;font-size:12px}@media print{button{display:none}}</style></head><body><div class="head"><div><h1>DOCUMENT PREVIEW</h1><div>Unsaved preview</div></div><div class="doc"><b>'+esc(title)+'</b><div>'+esc(number||'Draft')+'</div></div></div><div class="meta">'+Object.entries(meta||{}).map(([k,v])=>'<div><b>'+esc(k)+':</b> '+esc(v)+'</div>').join('')+'</div><table><thead><tr><th>Item / Description</th><th class="right">Qty</th><th class="right">Unit</th><th class="right">Total</th></tr></thead><tbody>'+rows+'</tbody></table><div class="total">'+esc(currency)+' '+Number(total||0).toLocaleString()+'</div><div class="note">Preview only — this document has not been saved or posted.</div><button onclick="window.print()">Print Preview</button></body></html>');w.document.close()}

async function loadDashboard(){setActive('Dashboard');const d=await api('/dashboard');const trial=d.business?.trial_ends_at?Math.max(0,Math.ceil((new Date(d.business.trial_ends_at)-Date.now())/86400000)):null;$('view').innerHTML=`<div class="panel banner"><div><b>${esc(d.business?.name||'Business')}</b><span>${esc(d.business?.status||'active')}${trial!==null?' · '+trial+' trial days left':''}</span></div><button class="secondary" onclick="openModule('Settings')">Manage plan</button></div><div class="kpi-grid">${card('Revenue Today',money(d.revenueToday),'Across all payments','green')}${card('Gross Profit',money(d.grossProfitToday),'From product cost','blue')}${card('Sales Today',d.salesToday,'Completed receipts','purple')}${card('Expenses Today',money(d.expensesToday),'Operating costs','orange')}${card('Low Stock',d.lowStock,'Needs attention',d.lowStock?'red':'')}${card('Month Revenue',money(d.revenueMonth),'Current month')}</div><div class="two-col"><div class="panel"><div class="panel-head"><h3>Recent sales</h3></div><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Cashier</th><th>Payment</th><th class="right">Total</th></tr></thead><tbody>${d.recentSales.map(x=>`<tr><td>${esc(x.receipt_no)}</td><td>${esc(x.cashier)}</td><td><span class="pill">${esc(x.payment_method)}</span></td><td class="right">${money(x.total)}</td></tr>`).join('')||'<tr><td colspan=4>No sales yet</td></tr>'}</tbody></table></div></div><div class="panel"><h3>Best sellers · 30 days</h3>${d.bestSellers.map(x=>`<div class="rank"><div><b>${esc(x.product_name)}</b><small>${Number(x.qty)} units</small></div><strong>${money(x.total)}</strong></div>`).join('')||'<div class="empty">No sales yet</div>'}</div></div>`}
async function openModule(m){setActive(m);if(m==='Dashboard')return loadDashboard();if(m==='SaaS Admin')return saas();if(!enabledModules.includes(m)&&user.role!=='saas_admin'){return $('view').innerHTML='<div class="panel"><h3>Add-on not enabled</h3><p class="muted">Ask your SaaS administrator to enable this module for your tenant.</p></div>'}if(m==='POS')return pos();if(m==='Orders')return orders();if(m==='Restaurant')return restaurant();if(m==='Products')return products(m);if(m==='Inventory')return inventory();if(m==='Customers')return people('customers','Customer');if(m==='Approvals')return approvals();if(m==='Suppliers')return suppliers();if(m==='Purchasing')return purchasing();if(m==='Expenses')return expenses();if(m==='Cash Drawer')return cash();if(m==='Settings')return settings();$('view').innerHTML=`<div class="panel"><div class="panel-head"><h3>${m}</h3><span class="pill">Enabled</span></div><p class="muted">This add-on is enabled for this tenant. Deeper workflow screens are being added.</p></div>`}
async function saas(){if(user.role!=='saas_admin')return;const tenants=await api('/saas/tenants');$('view').innerHTML=`<div class="kpi-grid">${card('Tenants',tenants.length,'Registered businesses','blue')}${card('Trials',tenants.filter(x=>x.status==='trial').length,'Active trials','purple')}${card('Active',tenants.filter(x=>x.status==='active').length,'Paid/active','green')}</div><div class="panel"><div class="panel-head"><h3>Tenant control</h3><span class="muted">Turn modules on/off and override prices per tenant</span></div><div class="table-wrap"><table><thead><tr><th>Business</th><th>Country</th><th>Status</th><th>Trial ends</th><th>Users</th><th></th></tr></thead><tbody>${tenants.map(t=>`<tr><td><b>${esc(t.name)}</b></td><td>${esc(t.country)}</td><td><span class="pill">${esc(t.status)}</span></td><td>${t.trial_ends_at?new Date(t.trial_ends_at).toLocaleDateString():'—'}</td><td>${t.users}</td><td class="right"><button class="secondary" onclick="tenantModules(${t.id},'${esc(t.name).replace(/'/g,"&#39;")}')">Modules</button></td></tr>`).join('')}</tbody></table></div></div><div id="tenantModules"></div>`}
async function tenantModules(id,name){const rows=await api('/saas/tenants/'+id+'/modules');$('tenantModules').innerHTML=`<div class="panel"><div class="panel-head"><h3>${esc(name)} · Add-ons</h3></div><div class="modules">${rows.map(x=>`<div class="module"><h3>${esc(x.name)}</h3><p class="muted">${esc(x.description||'')}</p><div class="price">${money(x.price_override??x.monthly_price)}/mo</div><label><input type="checkbox" ${x.enabled?'checked':''} onchange="toggleModule(${id},'${x.code}',this.checked,${Number(x.price_override??x.monthly_price)})"> Enabled</label><input id="price-${id}-${x.code}" type="number" value="${Number(x.price_override??x.monthly_price)}" placeholder="Monthly price"><button class="secondary" onclick="saveModulePrice(${id},'${x.code}',${x.enabled?'true':'false'})">Save price</button></div>`).join('')}</div></div>`}
async function toggleModule(id,code,enabled,price){await api('/saas/tenants/'+id+'/modules/'+code,{method:'PUT',body:JSON.stringify({enabled,priceOverride:price,trial:false})})}
async function saveModulePrice(id,code,enabled){await api('/saas/tenants/'+id+'/modules/'+code,{method:'PUT',body:JSON.stringify({enabled,priceOverride:Number($('price-'+id+'-'+code).value),trial:false})});alert('Module price updated')}
async function products(label='Products'){const ps=await api('/products');$('view').innerHTML=`<div class="panel"><div class="panel-head"><h3>${label}</h3><button onclick="productForm()">+ Add product</button></div><div id="form"></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>SKU</th><th>Barcode</th><th>Suppliers</th><th class="right">Price</th><th class="right">Stock</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${esc(p.category)}</td><td>${esc(p.sku||'-')}</td><td>${esc(p.barcode||'-')}</td><td>${(p.suppliers||[]).map(s=>`<span class="pill">${esc(s.name)}</span>`).join(' ')||'<span class="muted">None assigned</span>'}</td><td class="right">${money(p.price)}</td><td class="right">${p.stock}</td><td class="right"><button class="secondary" onclick="manageProductSuppliers(${p.id},'${esc(p.name).replace(/'/g,"&#39;")}')">Suppliers</button></td></tr>`).join('')}</tbody></table></div></div>`}
async function productForm(){const sups=await api('/suppliers');$('form').innerHTML=`<div class="inline-form"><input id="pn" placeholder="Product name"><input id="psku" placeholder="SKU"><input id="pbar" placeholder="Barcode"><input id="pcat" placeholder="Category"><input id="pcost" type="number" min="0" placeholder="Cost"><input id="pprice" type="number" min="0" placeholder="Price"><input id="pstock" type="number" min="0" placeholder="Opening stock"><div class="selection-box"><b>Supplied by</b><small>Select all suppliers that can supply this product.</small><div class="check-grid">${sups.map(s=>`<label><input type="checkbox" data-product-supplier="${s.id}"> ${esc(s.name)}</label>`).join('')||'<span class="muted">No suppliers registered yet.</span>'}</div></div><button onclick="saveProduct()">Save product</button></div>`}
async function saveProduct(){const supplierIds=[...document.querySelectorAll('[data-product-supplier]:checked')].map(x=>Number(x.dataset.productSupplier));await api('/products',{method:'POST',body:JSON.stringify({name:$('pn').value,sku:$('psku').value,barcode:$('pbar').value,category:$('pcat').value,cost:$('pcost').value,price:$('pprice').value,stock:$('pstock').value,supplierIds})});products('Products')}
async function manageProductSuppliers(id,name){const [sups,ps]=await Promise.all([api('/suppliers'),api('/products')]),p=ps.find(x=>Number(x.id)===Number(id)),chosen=new Set((p?.suppliers||[]).map(x=>Number(x.id)));$('form').innerHTML=`<div class="relation-editor"><div><h4>${esc(name)} - Suppliers</h4><p class="muted">Choose every supplier allowed to supply this product.</p></div><div class="check-grid">${sups.map(s=>`<label><input type="checkbox" data-edit-product-supplier="${s.id}" ${chosen.has(Number(s.id))?'checked':''}> ${esc(s.name)}</label>`).join('')||'<span class="muted">No suppliers registered.</span>'}</div><button onclick="saveProductSuppliers(${id})">Save supplier list</button></div>`}
async function saveProductSuppliers(id){const supplierIds=[...document.querySelectorAll('[data-edit-product-supplier]:checked')].map(x=>Number(x.dataset.editProductSupplier));await api('/products/'+id+'/suppliers',{method:'PUT',body:JSON.stringify({supplierIds})});products('Products')}

async function inventory(){const [o,locs,bals,transfers,counts,moves,branches]=await Promise.all([api('/inventory/overview'),api('/inventory/locations'),api('/inventory/balances'),api('/inventory/transfers'),api('/inventory/counts'),api('/stock-movements'),api('/branches')]);const locRows=locs.map(l=>'<tr><td><b>'+esc(l.name)+'</b><small>'+esc(l.location_type)+'</small></td><td>'+esc(l.branch_name)+'</td><td>'+Number(l.total_units)+'</td><td>'+money(l.stock_value)+'</td><td>'+(l.is_default?'<span class="pill">Default</span>':'')+'</td></tr>').join('')||'<tr><td colspan="5">No stock locations.</td></tr>';const balRows=bals.map(x=>'<tr><td><b>'+esc(x.product_name)+'</b><small>'+esc(x.sku||'')+'</small></td><td>'+esc(x.branch_name)+'</td><td>'+esc(x.location_name)+'</td><td>'+Number(x.qty)+'</td><td>'+money(x.avg_cost)+'</td><td>'+money(Number(x.qty)*Number(x.avg_cost))+'</td></tr>').join('')||'<tr><td colspan="6">No location balances yet.</td></tr>';const transferRows=transfers.slice(0,10).map(x=>'<tr><td><b>'+esc(x.reference_no)+'</b></td><td>'+esc(x.from_location)+'</td><td>'+esc(x.to_location)+'</td><td>'+Number(x.total_qty)+'</td><td>'+new Date(x.created_at).toLocaleString()+'</td></tr>').join('')||'<tr><td colspan="5">No transfers yet.</td></tr>';const countRows=counts.slice(0,10).map(x=>'<tr><td><b>'+esc(x.reference_no)+'</b></td><td>'+esc(x.location_name)+'</td><td><span class="pill">'+esc(x.status)+'</span></td><td>'+new Date(x.created_at).toLocaleString()+'</td><td class="right">'+(x.status==='draft'?'<button onclick="openStockCount('+x.id+')">Count stock</button>':'')+'</td></tr>').join('')||'<tr><td colspan="5">No stock counts yet.</td></tr>';const moveRows=moves.slice(0,20).map(x=>'<tr><td>'+new Date(x.created_at).toLocaleString()+'</td><td><b>'+esc(x.product_name)+'</b></td><td>'+esc(x.branch_name||'')+'</td><td><span class="pill">'+esc(x.movement_type)+'</span></td><td>'+Number(x.quantity)+'</td><td>'+esc(x.reference_no||'-')+'</td></tr>').join('')||'<tr><td colspan="6">No stock movements.</td></tr>';$('view').innerHTML='<div class="kpi-grid purchase-kpis">'+card('Locations',o.locations,'Active stock locations','blue')+card('Stock Value',money(o.stockValue),'Across all locations','green')+card('Low Stock',o.lowStock,'At or below reorder level',o.lowStock?'red':'')+card('Open Counts',o.openCounts,'Draft physical counts','purple')+'</div><div class="panel"><div class="panel-head"><div><h3>Inventory Control</h3><p class="muted">Location-based stock, transfers, adjustments, wastage and physical counts.</p></div><div class="action-row"><button class="secondary" onclick="ingredientManager()">Ingredients</button><button class="secondary" onclick="recipeManager()">Recipes</button><button class="secondary" onclick="unitManager()">Units</button><button class="secondary" onclick="consumptionForm()">Staff / Complimentary</button><button class="secondary" onclick="newInventoryLocation()">+ Location</button><button class="secondary" onclick="newStockAdjustment()">Adjustment</button><button class="secondary" onclick="newStockTransfer()">Transfer</button><button onclick="newStockCount()">Stock Count</button></div></div><div id="inventoryWork"></div></div><div class="two-col"><div class="panel"><h3>Stock Locations</h3><div class="table-wrap"><table><thead><tr><th>Location</th><th>Branch</th><th>Units</th><th>Value</th><th></th></tr></thead><tbody>'+locRows+'</tbody></table></div></div><div class="panel"><h3>Recent Transfers</h3><div class="table-wrap"><table><thead><tr><th>Reference</th><th>From</th><th>To</th><th>Qty</th><th>Date</th></tr></thead><tbody>'+transferRows+'</tbody></table></div></div></div><div class="panel"><h3>Location Balances</h3><div class="table-wrap"><table><thead><tr><th>Product</th><th>Branch</th><th>Location</th><th>Qty</th><th>Avg Cost</th><th>Value</th></tr></thead><tbody>'+balRows+'</tbody></table></div></div><div class="two-col"><div class="panel"><h3>Physical Stock Counts</h3><div class="table-wrap"><table><thead><tr><th>Count</th><th>Location</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody>'+countRows+'</tbody></table></div></div><div class="panel"><h3>Recent Stock Movements</h3><div class="table-wrap"><table><thead><tr><th>Date</th><th>Product</th><th>Branch</th><th>Type</th><th>Qty</th><th>Reference</th></tr></thead><tbody>'+moveRows+'</tbody></table></div></div></div>';window._inventoryLocations=locs;window._inventoryBranches=branches;window._inventoryBalances=bals}
async function newInventoryLocation(){const branches=window._inventoryBranches||await api('/branches');$('inventoryWork').innerHTML='<div class="inventory-editor"><h4>New Stock Location</h4><div class="form-row"><label>Branch<select id="invBranch">'+branches.map(b=>'<option value="'+b.id+'">'+esc(b.name)+'</option>').join('')+'</select></label><label>Location name<input id="invLocName" placeholder="e.g. Kitchen Store"></label><label>Type<select id="invLocType"><option value="store">Store</option><option value="kitchen">Kitchen</option><option value="bar">Bar</option><option value="cold_room">Cold Room</option><option value="freezer">Freezer</option><option value="packaging">Packaging</option></select></label></div><div class="builder-actions"><button class="secondary" onclick="inventory()">Cancel</button><button onclick="saveInventoryLocation()">Save Location</button></div></div>'}
async function saveInventoryLocation(){await api('/inventory/locations',{method:'POST',body:JSON.stringify({branchId:Number($('invBranch').value),name:$('invLocName').value,locationType:$('invLocType').value})});inventory()}
async function newStockAdjustment(){const [locs,products]=await Promise.all([api('/inventory/locations'),api('/products')]);$('inventoryWork').innerHTML='<div class="inventory-editor"><h4>Stock Adjustment / Wastage</h4><div class="form-row"><label>Location<select id="adjLocation">'+locs.map(l=>'<option value="'+l.id+'">'+esc(l.branch_name)+' · '+esc(l.name)+'</option>').join('')+'</select></label><label>Type<select id="adjType"><option value="adjustment">Adjustment</option><option value="wastage">Wastage</option><option value="spoilage">Spoilage</option></select></label><label>Reason<input id="adjReason" placeholder="Reason"></label></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Quantity change</th><th>Unit cost</th><th></th></tr></thead><tbody id="adjLines"></tbody></table></div><div class="form-row"><label>Add product<select id="adjProduct"><option value="">Choose product</option>'+products.map(p=>'<option value="'+p.id+'" data-cost="'+Number(p.cost)+'">'+esc(p.name)+'</option>').join('')+'</select></label><button onclick="addAdjustmentLine()" type="button">Add Item</button></div><div class="builder-actions"><button class="secondary" onclick="inventory()">Cancel</button><button onclick="postAdjustment()">Post Adjustment</button></div></div>';window._adjItems=[]}
function addAdjustmentLine(){const sel=$('adjProduct'),pid=Number(sel.value);if(!pid)return;const opt=sel.options[sel.selectedIndex],name=opt.text,cost=Number(opt.dataset.cost||0);if(!window._adjItems.find(x=>x.productId===pid))window._adjItems.push({productId:pid,name,qtyChange:-1,unitCost:cost});renderAdjustmentLines()}
function renderAdjustmentLines(){const body=$('adjLines');if(!body)return;body.innerHTML=window._adjItems.map((x,i)=>'<tr><td><b>'+esc(x.name)+'</b></td><td><input class="mini-input" type="number" step="0.001" value="'+x.qtyChange+'" onchange="_adjItems['+i+'].qtyChange=Number(this.value)"></td><td><input class="mini-input" type="number" min="0" value="'+x.unitCost+'" onchange="_adjItems['+i+'].unitCost=Number(this.value)"></td><td><button class="ghost" onclick="_adjItems.splice('+i+',1);renderAdjustmentLines()">Remove</button></td></tr>').join('')}
async function postAdjustment(){if(!window._adjItems?.length)return alert('Add at least one product');const r=await api('/inventory/adjustments',{method:'POST',body:JSON.stringify({locationId:Number($('adjLocation').value),adjustmentType:$('adjType').value,reason:$('adjReason').value,items:window._adjItems})});if(r.pendingApproval)alert('Submitted for management approval. Stock will change only after approval.');inventory()}
async function newStockTransfer(){const locs=await api('/inventory/locations');$('inventoryWork').innerHTML='<div class="inventory-editor"><h4>Stock Transfer</h4><div class="form-row"><label>From<select id="trFrom" onchange="loadTransferProducts()"><option value="">Choose source</option>'+locs.map(l=>'<option value="'+l.id+'">'+esc(l.branch_name)+' · '+esc(l.name)+'</option>').join('')+'</select></label><label>To<select id="trTo"><option value="">Choose destination</option>'+locs.map(l=>'<option value="'+l.id+'">'+esc(l.branch_name)+' · '+esc(l.name)+'</option>').join('')+'</select></label><label>Notes<input id="trNotes" placeholder="Optional notes"></label></div><div id="trProducts"></div><div id="trLines"></div><div class="builder-actions"><button class="secondary" onclick="inventory()">Cancel</button><button onclick="postTransfer()">Post Transfer</button></div></div>';window._transferItems=[];window._transferProducts=[]}
async function loadTransferProducts(){const lid=Number($('trFrom').value);window._transferItems=[];renderTransferLines();if(!lid){$('trProducts').innerHTML='';return}const bals=await api('/inventory/balances?locationId='+lid);window._transferProducts=bals.filter(x=>Number(x.qty)>0);$('trProducts').innerHTML='<div class="product-grid">'+(window._transferProducts.map(p=>'<button class="product-tile" data-tr-product="'+p.product_id+'"><b>'+esc(p.product_name)+'</b><span>'+Number(p.qty)+' available</span><small>'+esc(p.sku||'')+'</small></button>').join('')||'<div class="empty">No stock available at this location.</div>')+'</div>';document.querySelectorAll('[data-tr-product]').forEach(btn=>btn.addEventListener('click',()=>addTransferLine(Number(btn.dataset.trProduct))))}
function addTransferLine(pid){const p=window._transferProducts.find(x=>Number(x.product_id)===pid);if(!p)return;const x=window._transferItems.find(i=>i.productId===pid);if(x){if(x.qty<Number(p.qty))x.qty++}else window._transferItems.push({productId:pid,name:p.product_name,qty:1,max:Number(p.qty)});renderTransferLines()}
function renderTransferLines(){if(!$('trLines'))return;$('trLines').innerHTML=window._transferItems.length?'<div class="table-wrap"><table><thead><tr><th>Product</th><th>Available</th><th>Transfer Qty</th><th></th></tr></thead><tbody>'+window._transferItems.map((x,i)=>'<tr><td><b>'+esc(x.name)+'</b></td><td>'+x.max+'</td><td><input class="mini-input" type="number" min="0.001" max="'+x.max+'" step="0.001" value="'+x.qty+'" onchange="_transferItems['+i+'].qty=Number(this.value)"></td><td><button class="ghost" onclick="_transferItems.splice('+i+',1);renderTransferLines()">Remove</button></td></tr>').join('')+'</tbody></table></div>':'<div class="empty">Choose a source location and add products.</div>'}
async function postTransfer(){if(!$('trFrom').value||!$('trTo').value)return alert('Choose source and destination');if(Number($('trFrom').value)===Number($('trTo').value))return alert('Source and destination must be different');if(!window._transferItems?.length)return alert('Add products to transfer');await api('/inventory/transfers',{method:'POST',body:JSON.stringify({fromLocationId:Number($('trFrom').value),toLocationId:Number($('trTo').value),notes:$('trNotes').value,items:window._transferItems.map(x=>({productId:x.productId,qty:x.qty}))})});inventory()}
async function newStockCount(){const locs=await api('/inventory/locations');$('inventoryWork').innerHTML='<div class="inventory-editor"><h4>Start Physical Stock Count</h4><div class="form-row"><label>Location<select id="countLocation">'+locs.map(l=>'<option value="'+l.id+'">'+esc(l.branch_name)+' · '+esc(l.name)+'</option>').join('')+'</select></label><label>Notes<input id="countNotes" placeholder="Optional notes"></label></div><div class="builder-actions"><button class="secondary" onclick="inventory()">Cancel</button><button onclick="createStockCount()">Start Count</button></div></div>'}
async function createStockCount(){const c=await api('/inventory/counts',{method:'POST',body:JSON.stringify({locationId:Number($('countLocation').value),notes:$('countNotes').value})});openStockCount(c.id)}
async function openStockCount(id){const d=await api('/inventory/counts/'+id);const rows=d.items.map(x=>'<tr><td><b>'+esc(x.product_name)+'</b><small>'+esc(x.sku||'')+'</small></td><td>'+Number(x.expected_qty)+'</td><td><input class="mini-input count-value" data-item="'+x.id+'" data-expected="'+Number(x.expected_qty)+'" type="number" min="0" step="0.001" value="'+(x.counted_qty??x.expected_qty)+'"></td><td class="variance">'+(Number(x.counted_qty??x.expected_qty)-Number(x.expected_qty)).toFixed(3)+'</td></tr>').join('');$('inventoryWork').innerHTML='<div class="inventory-editor"><h4>'+esc(d.count.reference_no)+' · '+esc(d.count.location_name)+'</h4><p class="muted">Enter the physical quantity actually counted for every product.</p><div class="table-wrap"><table><thead><tr><th>Product</th><th>Expected</th><th>Counted</th><th>Variance</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="builder-actions"><button class="secondary" onclick="inventory()">Save for later</button><button onclick="postStockCount('+id+')">Post Count & Adjust Stock</button></div></div>';document.querySelectorAll('.count-value').forEach(inp=>inp.addEventListener('input',()=>{const variance=Number(inp.value)-Number(inp.dataset.expected);inp.closest('tr').querySelector('.variance').textContent=variance.toFixed(3)}))}
async function postStockCount(id){const items=[...document.querySelectorAll('.count-value')].map(x=>({itemId:Number(x.dataset.item),countedQty:Number(x.value)}));await api('/inventory/counts/'+id+'/post',{method:'POST',body:JSON.stringify({items})});inventory()}

async function approvals(){const [pending,approved,rejected,rules,staff]=await Promise.all([api('/approvals?status=pending'),api('/approvals?status=approved'),api('/approvals?status=rejected'),api('/approval-rules'),api('/staff')]);const pendingRows=pending.map(a=>'<tr><td><b>'+esc(a.reference_no||('#'+a.id))+'</b><small>'+new Date(a.requested_at).toLocaleString()+'</small></td><td>'+esc(a.section)+'</td><td>'+esc(a.title)+'</td><td>'+esc(a.requested_by_name||'')+'</td><td class="right">'+(a.amount!=null?money(a.amount):'-')+'</td><td>'+esc(a.request_comment||'-')+'</td><td class="right"><button class="secondary" data-reject-approval="'+a.id+'">Reject</button> <button data-approve-approval="'+a.id+'">Approve</button></td></tr>').join('')||'<tr><td colspan="7"><div class="empty">No approvals waiting for you.</div></td></tr>';const history=[...approved,...rejected].sort((x,y)=>new Date(y.decided_at||0)-new Date(x.decided_at||0)).slice(0,25);const historyRows=history.map(a=>'<tr><td><b>'+esc(a.reference_no||('#'+a.id))+'</b></td><td>'+esc(a.section)+'</td><td><span class="pill">'+esc(a.status)+'</span></td><td>'+esc(a.decided_by_name||'')+'</td><td>'+esc(a.decision_comment||'-')+'</td><td>'+new Date(a.decided_at).toLocaleString()+'</td></tr>').join('')||'<tr><td colspan="6">No approval history yet.</td></tr>';const actionNames={purchase_order:'Purchase Orders',inventory_wastage:'Wastage',inventory_spoilage:'Spoilage',restaurant_order_cancel:'Order Cancellation'};const ruleCards=rules.map(r=>'<div class="approval-rule"><div><b>'+esc(actionNames[r.action_type]||r.action_type)+'</b><small>'+esc(r.section)+'</small></div><select id="approver-'+r.action_type+'"><option value="">By role: '+esc(r.approver_role||'owner')+'</option>'+staff.map(s=>'<option value="'+s.id+'" '+(String(s.id)===String(r.approver_user_id||'')?'selected':'')+'>'+esc(s.name)+' · '+esc(s.role)+'</option>').join('')+'</select><button class="secondary approval-rule-save" data-action="'+esc(r.action_type)+'" data-section="'+esc(r.section)+'">Assign Supervisor</button></div>').join('');$('view').innerHTML='<div class="panel"><div class="panel-head"><div><h3>Approval Center</h3><p class="muted">Sensitive transactions execute only after the responsible supervisor or management approves them.</p></div><span class="pill">'+pending.length+' pending</span></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Section</th><th>Request</th><th>Requested By</th><th class="right">Amount</th><th>Request Comment</th><th></th></tr></thead><tbody>'+pendingRows+'</tbody></table></div></div><div class="panel"><div class="panel-head"><div><h3>Approval History</h3><p class="muted">Approved and rejected requests with management comments.</p></div></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Section</th><th>Decision</th><th>Decided By</th><th>Comment</th><th>Date</th></tr></thead><tbody>'+historyRows+'</tbody></table></div></div><div class="panel"><div class="panel-head"><div><h3>Approval Routing</h3><p class="muted">Assign the respective supervisor for each controlled action. Owners/admins keep management override authority.</p></div></div><div class="approval-rules">'+ruleCards+'</div></div>';document.querySelectorAll('[data-approve-approval]').forEach(b=>b.addEventListener('click',()=>approveApproval(Number(b.dataset.approveApproval))));document.querySelectorAll('[data-reject-approval]').forEach(b=>b.addEventListener('click',()=>rejectApproval(Number(b.dataset.rejectApproval))));document.querySelectorAll('.approval-rule-save').forEach(b=>b.addEventListener('click',()=>saveApprovalRule(b.dataset.action,b.dataset.section)))}
async function approveApproval(id){const r=await appPrompt({title:'Approve Request',message:'Add an optional management comment before approving.',placeholder:'Approval comment',confirmText:'Approve'});if(!r)return;await api('/approvals/'+id+'/approve',{method:'POST',body:JSON.stringify({comment:r.comment})});showToast('Request approved');approvals()}
async function rejectApproval(id){const r=await appPrompt({title:'Reject Request',message:'A clear reason is required and will be recorded in the approval history.',placeholder:'Reason for rejection',required:true,confirmText:'Reject Request',danger:true});if(!r)return;await api('/approvals/'+id+'/reject',{method:'POST',body:JSON.stringify({comment:r.comment})});showToast('Request rejected','warning');approvals()}
async function saveApprovalRule(actionType,section){const v=$('approver-'+actionType).value;await api('/approval-rules/'+actionType,{method:'PUT',body:JSON.stringify({section,approverUserId:v?Number(v):null,approverRole:v?null:'owner'})});alert('Approval supervisor updated');approvals()}


let ingredientCache=[],unitCache=[],recipeLineDraft=[],recipeIngredients=[],recipeUnits=[],recipeLocations=[];

let restaurantCache={branches:[],areas:[],tables:[],stations:[],categories:[],menuItems:[],modifierGroups:[],products:[]};
async function restaurant(){const [o,areas,tables,stations,categories,menuItems,mods,branches]=await Promise.all([api('/restaurant/overview'),api('/restaurant/areas'),api('/restaurant/tables'),api('/restaurant/stations'),api('/menu/categories'),api('/menu/items'),api('/menu/modifier-groups'),api('/branches')]);restaurantCache={...restaurantCache,areas,tables,stations,categories,menuItems,modifierGroups:mods,branches};$('view').innerHTML='<div class="kpi-grid purchase-kpis">'+card('Tables',o.tables,'Configured tables','blue')+card('Occupied',o.occupied,'Currently occupied','purple')+card('Available Menu',o.availableMenu,'Items available now','green')+card('Sold Out',o.soldOut,'Hidden from ordering',o.soldOut?'red':'')+'</div><div class="panel"><div class="panel-head"><div><h3>Restaurant Setup</h3><p class="muted">Configure floor operations, kitchen routing and the complete restaurant menu.</p></div></div><div class="restaurant-launcher"><button onclick="floorManager()">Floor & Tables</button><button onclick="stationManager()">Kitchen Stations</button><button onclick="categoryManager()">Menu Categories</button><button onclick="menuManager()">Menu Items</button><button onclick="modifierManager()">Modifiers</button><button onclick="comboManager()">Combos</button></div><div id="restaurantWork"></div></div>'}

async function floorManager(){const [areas,tables,branches]=await Promise.all([api('/restaurant/areas'),api('/restaurant/tables'),api('/branches')]);restaurantCache.areas=areas;restaurantCache.tables=tables;restaurantCache.branches=branches;const areaCards=areas.map(a=>'<div class="floor-area"><div class="floor-area-head"><div><b>'+esc(a.name)+'</b><small>'+esc(a.branch_name)+' · '+a.table_count+' tables</small></div><button class="secondary add-table" data-area="'+a.id+'" data-branch="'+a.branch_id+'">+ Table</button></div><div class="table-grid">'+tables.filter(t=>Number(t.area_id)===Number(a.id)).map(t=>'<div class="table-card status-'+esc(t.status.replaceAll(' ','_'))+'"><div><b>'+esc(t.name)+'</b><small>'+t.capacity+' seats</small></div><select class="table-status" data-id="'+t.id+'"><option value="available" '+(t.status==='available'?'selected':'')+'>Available</option><option value="occupied" '+(t.status==='occupied'?'selected':'')+'>Occupied</option><option value="reserved" '+(t.status==='reserved'?'selected':'')+'>Reserved</option><option value="waiting_for_bill" '+(t.status==='waiting_for_bill'?'selected':'')+'>Waiting for Bill</option><option value="cleaning" '+(t.status==='cleaning'?'selected':'')+'>Cleaning</option></select></div>').join('')+'</div></div>').join('')||'<div class="empty">Create a dining area first.</div>';$('restaurantWork').innerHTML='<div class="submodule-head"><div><h4>Floor & Tables</h4><p>Areas, table capacity and live table statuses.</p></div><button onclick="areaForm()">+ Dining Area</button></div><div id="restaurantForm"></div><div class="floor-layout">'+areaCards+'</div>';document.querySelectorAll('.add-table').forEach(b=>b.addEventListener('click',()=>tableForm(Number(b.dataset.area),Number(b.dataset.branch))));document.querySelectorAll('.table-status').forEach(s=>s.addEventListener('change',()=>updateTableStatus(Number(s.dataset.id),s.value)))}
function areaForm(){const branches=restaurantCache.branches;$('restaurantForm').innerHTML='<div class="inline-editor"><label>Branch<select id="areaBranch">'+branches.map(b=>'<option value="'+b.id+'">'+esc(b.name)+'</option>').join('')+'</select></label><label>Area / Floor<input id="areaName" placeholder="e.g. Main Dining, Terrace"></label><button onclick="saveArea()">Save Area</button></div>'}
async function saveArea(){await api('/restaurant/areas',{method:'POST',body:JSON.stringify({branchId:Number($('areaBranch').value),name:$('areaName').value})});showToast('Dining area created');floorManager()}
function tableForm(areaId,branchId){$('restaurantForm').innerHTML='<div class="inline-editor"><label>Table name<input id="tableName" placeholder="e.g. Table 01"></label><label>Code<input id="tableCode" placeholder="T01"></label><label>Capacity<input id="tableCapacity" type="number" min="1" value="2"></label><button onclick="saveTable('+areaId+','+branchId+')">Save Table</button></div>'}
async function saveTable(areaId,branchId){await api('/restaurant/tables',{method:'POST',body:JSON.stringify({areaId,branchId,name:$('tableName').value,code:$('tableCode').value,capacity:Number($('tableCapacity').value)})});showToast('Table created');floorManager()}
async function updateTableStatus(id,status){const t=restaurantCache.tables.find(x=>Number(x.id)===id);await api('/restaurant/tables/'+id,{method:'PUT',body:JSON.stringify({areaId:t.area_id,name:t.name,code:t.code,capacity:t.capacity,status,sortOrder:t.sort_order,active:true})});showToast('Table status updated');floorManager()}

async function stationManager(){const [stations,branches]=await Promise.all([api('/restaurant/stations'),api('/branches')]);restaurantCache.stations=stations;restaurantCache.branches=branches;const rows=stations.map(s=>'<tr><td><b>'+esc(s.name)+'</b></td><td>'+esc(s.branch_name)+'</td><td>'+esc(s.station_type)+'</td><td>'+esc(s.printer_name||'-')+'</td></tr>').join('')||'<tr><td colspan="4">No kitchen stations.</td></tr>';$('restaurantWork').innerHTML='<div class="submodule-head"><div><h4>Kitchen Stations</h4><p>Route menu items to Kitchen, Bar, Coffee, Grill, Pizza and other stations.</p></div></div><div class="inline-editor"><label>Branch<select id="stationBranch">'+branches.map(b=>'<option value="'+b.id+'">'+esc(b.name)+'</option>').join('')+'</select></label><label>Station name<input id="stationName" placeholder="e.g. Main Kitchen"></label><label>Type<select id="stationType"><option value="kitchen">Kitchen</option><option value="bar">Bar</option><option value="coffee">Coffee</option><option value="grill">Grill</option><option value="pizza">Pizza</option></select></label><label>Printer name<input id="stationPrinter" placeholder="Optional printer"></label><button onclick="saveStation()">Add Station</button></div><div class="table-wrap"><table><thead><tr><th>Station</th><th>Branch</th><th>Type</th><th>Printer</th></tr></thead><tbody>'+rows+'</tbody></table></div>'}
async function saveStation(){await api('/restaurant/stations',{method:'POST',body:JSON.stringify({branchId:Number($('stationBranch').value),name:$('stationName').value,stationType:$('stationType').value,printerName:$('stationPrinter').value})});showToast('Kitchen station created');stationManager()}

async function categoryManager(){const [cats,stations]=await Promise.all([api('/menu/categories'),api('/restaurant/stations')]);restaurantCache.categories=cats;restaurantCache.stations=stations;const rows=cats.map(c=>'<tr><td><b>'+esc(c.name)+'</b></td><td>'+esc(c.parent_name||'-')+'</td><td>'+esc(c.station_name||'-')+'</td><td>'+esc(c.description||'')+'</td></tr>').join('')||'<tr><td colspan="4">No menu categories.</td></tr>';$('restaurantWork').innerHTML='<div class="submodule-head"><div><h4>Menu Categories</h4><p>Categories and subcategories can also define default kitchen routing.</p></div></div><div class="inline-editor"><label>Name<input id="catName" placeholder="e.g. Main Course"></label><label>Parent<select id="catParent"><option value="">Top level</option>'+cats.map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join('')+'</select></label><label>Default Station<select id="catStation"><option value="">None</option>'+stations.map(s=>'<option value="'+s.id+'">'+esc(s.name)+' · '+esc(s.branch_name)+'</option>').join('')+'</select></label><label>Description<input id="catDesc" placeholder="Optional"></label><button onclick="saveCategory()">Add Category</button></div><div class="table-wrap"><table><thead><tr><th>Category</th><th>Parent</th><th>Station</th><th>Description</th></tr></thead><tbody>'+rows+'</tbody></table></div>'}
async function saveCategory(){await api('/menu/categories',{method:'POST',body:JSON.stringify({name:$('catName').value,parentId:Number($('catParent').value)||null,defaultStationId:Number($('catStation').value)||null,description:$('catDesc').value})});showToast('Menu category created');categoryManager()}

let modifierDraft=[];
async function modifierManager(){const groups=await api('/menu/modifier-groups');restaurantCache.modifierGroups=groups;const cards=groups.map(g=>'<div class="modifier-card"><div><b>'+esc(g.name)+'</b><small>'+(g.required?'Required':'Optional')+' · choose '+g.min_select+'–'+g.max_select+'</small></div><div class="modifier-chips">'+g.modifiers.map(m=>'<span class="pill">'+esc(m.name)+' '+(Number(m.price)?money(m.price):'')+'</span>').join('')+'</div><button class="secondary modifier-edit" data-id="'+g.id+'">Edit</button></div>').join('')||'<div class="empty">No modifier groups yet.</div>';$('restaurantWork').innerHTML='<div class="submodule-head"><div><h4>Modifier Groups</h4><p>Required/optional add-ons with minimum and maximum selection rules.</p></div><button onclick="modifierForm()">+ Modifier Group</button></div><div id="restaurantForm"></div><div class="modifier-list">'+cards+'</div>';document.querySelectorAll('.modifier-edit').forEach(b=>b.addEventListener('click',()=>modifierForm(Number(b.dataset.id))))}
function modifierForm(id=null){const g=id?restaurantCache.modifierGroups.find(x=>Number(x.id)===id):null;modifierDraft=g?g.modifiers.map(x=>({name:x.name,price:Number(x.price)})):[];$('restaurantForm').innerHTML='<div class="inventory-editor"><div class="form-row"><label>Group name<input id="modGroupName" value="'+esc(g?.name||'')+'" placeholder="e.g. Choose Sauce"></label><label>Required<select id="modRequired"><option value="false">Optional</option><option value="true" '+(g?.required?'selected':'')+'>Required</option></select></label><label>Minimum selections<input id="modMin" type="number" min="0" value="'+Number(g?.min_select||0)+'"></label><label>Maximum selections<input id="modMax" type="number" min="1" value="'+Number(g?.max_select||1)+'"></label></div><div class="recipe-add-line"><input id="modName" placeholder="Option name"><input id="modPrice" type="number" min="0" value="0" placeholder="Extra price"><button onclick="addModifierOption()">Add Option</button></div><div id="modifierDraft"></div><div class="builder-actions"><button class="secondary" onclick="modifierManager()">Cancel</button><button onclick="saveModifierGroup('+(id||'null')+')">Save Modifier Group</button></div></div>';renderModifierDraft()}
function addModifierOption(){if(!$('modName').value.trim())return;modifierDraft.push({name:$('modName').value.trim(),price:Number($('modPrice').value||0)});$('modName').value='';$('modPrice').value='0';renderModifierDraft()}
function renderModifierDraft(){if(!$('modifierDraft'))return;$('modifierDraft').innerHTML=modifierDraft.map((m,i)=>'<div class="draft-line"><span><b>'+esc(m.name)+'</b> '+(m.price?money(m.price):'')+'</span><button class="ghost" onclick="modifierDraft.splice('+i+',1);renderModifierDraft()">Remove</button></div>').join('')||'<div class="empty">Add modifier options.</div>'}
async function saveModifierGroup(id){await api('/menu/modifier-groups',{method:'POST',body:JSON.stringify({id,name:$('modGroupName').value,required:$('modRequired').value==='true',minSelect:Number($('modMin').value),maxSelect:Number($('modMax').value),modifiers:modifierDraft})});showToast('Modifier group saved');modifierManager()}

let menuVariantDraft=[],menuScheduleDraft=[],menuItemDetail=null;
async function menuManager(){const items=await api('/menu/items');restaurantCache.menuItems=items;const rows=items.map(x=>'<tr><td><b>'+esc(x.product_name)+'</b><small>'+esc(x.category_name||'Uncategorized')+'</small></td><td>'+esc(x.station_name||'-')+'</td><td>'+money(x.base_price)+'</td><td>'+x.variant_count+'</td><td>'+x.modifier_group_count+'</td><td>'+(x.sold_out?'<span class="priority-urgent">SOLD OUT</span>':(x.available?'<span class="pill">Available</span>':'<span class="pill">Hidden</span>'))+'</td><td class="right"><button class="secondary menu-edit" data-id="'+x.id+'">Edit</button> <button class="secondary menu-toggle" data-id="'+x.id+'" data-available="'+x.available+'" data-sold="'+x.sold_out+'">'+(x.sold_out?'Mark Available':'Sold Out')+'</button></td></tr>').join('')||'<tr><td colspan="7">No menu items configured yet.</td></tr>';$('restaurantWork').innerHTML='<div class="submodule-head"><div><h4>Menu Items</h4><p>Restaurant menu metadata, pricing, schedules, variants and modifiers.</p></div><button onclick="menuItemForm()">+ Menu Item</button></div><div id="restaurantForm"></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Station</th><th>Base Price</th><th>Variants</th><th>Modifier Groups</th><th>Status</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div>';document.querySelectorAll('.menu-edit').forEach(b=>b.addEventListener('click',()=>menuItemForm(Number(b.dataset.id))));document.querySelectorAll('.menu-toggle').forEach(b=>b.addEventListener('click',()=>toggleMenuSoldOut(Number(b.dataset.id),b.dataset.sold==='true')))}
async function menuItemForm(id=null){const [products,cats,stations,mods,branches,detail]=await Promise.all([api('/products'),api('/menu/categories'),api('/restaurant/stations'),api('/menu/modifier-groups'),api('/branches'),id?api('/menu/items/'+id):Promise.resolve(null)]);menuItemDetail=detail;restaurantCache={...restaurantCache,products,categories:cats,stations,modifierGroups:mods,branches};menuVariantDraft=detail?detail.variants.map(v=>({name:v.name,sku:v.sku||'',priceDelta:Number(v.price_delta)})):[];menuScheduleDraft=detail?detail.schedules.map(s=>({dayOfWeek:Number(s.day_of_week),startTime:String(s.start_time).slice(0,5),endTime:String(s.end_time).slice(0,5)})):[];const mi=detail?.item,groupSet=new Set(detail?.modifierGroupIds||[]),priceMap=new Map((detail?.prices||[]).map(p=>[String(p.branch_id)+'|'+p.order_type,Number(p.price)]));const orderTypes=['all','dine_in','takeaway','delivery','counter'];const priceRows=branches.map(b=>'<tr><td><b>'+esc(b.name)+'</b></td>'+orderTypes.map(t=>'<td><input class="mini-input menu-price" data-branch="'+b.id+'" data-type="'+t+'" type="number" min="0" placeholder="'+(t==='all'?'Default':'Optional')+'" value="'+(priceMap.has(String(b.id)+'|'+t)?priceMap.get(String(b.id)+'|'+t):'')+'"></td>').join('')+'</tr>').join('');$('restaurantForm').innerHTML='<div class="inventory-editor menu-editor"><div class="form-row"><label>Product<select id="menuProduct">'+products.map(p=>'<option value="'+p.id+'" '+(Number(mi?.product_id)===Number(p.id)?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></label><label>Category<select id="menuCategory"><option value="">Uncategorized</option>'+cats.map(c=>'<option value="'+c.id+'" '+(Number(mi?.category_id)===Number(c.id)?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></label><label>Station override<select id="menuStation"><option value="">Use category station</option>'+stations.map(s=>'<option value="'+s.id+'" '+(Number(mi?.kitchen_station_id)===Number(s.id)?'selected':'')+'>'+esc(s.name)+' · '+esc(s.branch_name)+'</option>').join('')+'</select></label><label>Image URL<input id="menuImage" value="'+esc(mi?.image_url||'')+'" placeholder="Optional image URL"></label><label class="wide">Description<textarea id="menuDesc">'+esc(mi?.description||'')+'</textarea></label><label>Available<select id="menuAvailable"><option value="true" '+(mi?.available!==false?'selected':'')+'>Available</option><option value="false" '+(mi?.available===false?'selected':'')+'>Hidden</option></select></label><label>Sold Out<select id="menuSold"><option value="false" '+(!mi?.sold_out?'selected':'')+'>No</option><option value="true" '+(mi?.sold_out?'selected':'')+'>Yes</option></select></label><label>Sort order<input id="menuSort" type="number" value="'+Number(mi?.sort_order||0)+'"></label></div><h4>Variants / Sizes</h4><div class="recipe-add-line"><input id="variantName" placeholder="e.g. Large"><input id="variantSku" placeholder="Optional SKU"><input id="variantDelta" type="number" step="0.01" value="0" placeholder="Price +/-"><button onclick="addMenuVariant()">Add Variant</button></div><div id="variantDraft"></div><h4>Modifier Groups</h4><div class="check-grid">'+mods.map(g=>'<label><input type="checkbox" class="menu-mod-group" value="'+g.id+'" '+(groupSet.has(Number(g.id))?'checked':'')+'> '+esc(g.name)+'</label>').join('')+'</div><h4>Branch / Order-Type Pricing</h4><div class="table-wrap"><table><thead><tr><th>Branch</th><th>Default</th><th>Dine-in</th><th>Takeaway</th><th>Delivery</th><th>Counter</th></tr></thead><tbody>'+priceRows+'</tbody></table></div><h4>Availability Schedule</h4><div class="recipe-add-line"><select id="schedDay"><option value="0">Sunday</option><option value="1">Monday</option><option value="2">Tuesday</option><option value="3">Wednesday</option><option value="4">Thursday</option><option value="5">Friday</option><option value="6">Saturday</option></select><input id="schedStart" type="time" value="06:00"><input id="schedEnd" type="time" value="23:59"><button onclick="addMenuSchedule()">Add Schedule</button></div><div id="scheduleDraft"></div><div class="builder-actions"><button class="secondary" onclick="menuManager()">Cancel</button><button onclick="saveMenuItem('+(id||'null')+')">Save Menu Item</button></div></div>';renderVariantDraft();renderScheduleDraft()}
function addMenuVariant(){const name=$('variantName').value.trim();if(!name)return;menuVariantDraft.push({name,sku:$('variantSku').value.trim(),priceDelta:Number($('variantDelta').value||0)});$('variantName').value='';renderVariantDraft()}
function renderVariantDraft(){if(!$('variantDraft'))return;$('variantDraft').innerHTML=menuVariantDraft.map((v,i)=>'<div class="draft-line"><span><b>'+esc(v.name)+'</b> '+(v.priceDelta?(v.priceDelta>0?'+':'')+money(v.priceDelta):'')+'</span><button class="ghost" onclick="menuVariantDraft.splice('+i+',1);renderVariantDraft()">Remove</button></div>').join('')||'<div class="empty">No variants; the base product is used.</div>'}
function addMenuSchedule(){menuScheduleDraft.push({dayOfWeek:Number($('schedDay').value),startTime:$('schedStart').value,endTime:$('schedEnd').value});renderScheduleDraft()}
function renderScheduleDraft(){if(!$('scheduleDraft'))return;const days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];$('scheduleDraft').innerHTML=menuScheduleDraft.map((s,i)=>'<div class="draft-line"><span><b>'+days[s.dayOfWeek]+'</b> '+esc(s.startTime)+'–'+esc(s.endTime)+'</span><button class="ghost" onclick="menuScheduleDraft.splice('+i+',1);renderScheduleDraft()">Remove</button></div>').join('')||'<div class="empty">No schedule means available at all times.</div>'}
async function saveMenuItem(id){const prices=[...document.querySelectorAll('.menu-price')].filter(x=>x.value!=='').map(x=>({branchId:Number(x.dataset.branch),orderType:x.dataset.type,price:Number(x.value)})),modifierGroupIds=[...document.querySelectorAll('.menu-mod-group:checked')].map(x=>Number(x.value));await api('/menu/items',{method:'POST',body:JSON.stringify({id,productId:Number($('menuProduct').value),categoryId:Number($('menuCategory').value)||null,kitchenStationId:Number($('menuStation').value)||null,description:$('menuDesc').value,imageUrl:$('menuImage').value,available:$('menuAvailable').value==='true',soldOut:$('menuSold').value==='true',sortOrder:Number($('menuSort').value||0),variants:menuVariantDraft,modifierGroupIds,prices,schedules:menuScheduleDraft})});showToast('Menu item saved');menuManager()}
async function toggleMenuSoldOut(id,isSold){await api('/menu/items/'+id+'/availability',{method:'PUT',body:JSON.stringify({available:true,soldOut:!isSold})});showToast(isSold?'Item available again':'Item marked sold out');menuManager()}

let comboDraft=[];
async function comboManager(){const [combos,items,products]=await Promise.all([api('/menu/combos'),api('/menu/items'),api('/products')]);restaurantCache.menuItems=items;restaurantCache.products=products;const rows=combos.map(c=>'<tr><td><b>'+esc(c.name)+'</b><small>'+esc(c.product_name)+'</small></td><td>'+c.items.map(x=>esc(x.name)+' × '+Number(x.qty)).join(', ')+'</td><td>'+money(c.price)+'</td><td class="right"><button class="secondary combo-edit" data-id="'+c.id+'">Edit</button></td></tr>').join('')||'<tr><td colspan="4">No combos configured.</td></tr>';$('restaurantWork').innerHTML='<div class="submodule-head"><div><h4>Menu Combos</h4><p>Bundle existing menu items under a sellable combo product.</p></div><button onclick="comboForm()">+ Combo</button></div><div id="restaurantForm"></div><div class="table-wrap"><table><thead><tr><th>Combo</th><th>Contents</th><th>Selling Price</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div>';document.querySelectorAll('.combo-edit').forEach(b=>b.addEventListener('click',()=>comboForm(Number(b.dataset.id),combos)))}
function comboForm(id=null,combos=[]){const c=id?combos.find(x=>Number(x.id)===id):null;comboDraft=c?c.items.map(x=>({menuItemId:Number(x.menuItemId),name:x.name,qty:Number(x.qty),required:x.required!==false})):[];$('restaurantForm').innerHTML='<div class="inventory-editor"><div class="form-row"><label>Sellable combo product<select id="comboProduct">'+restaurantCache.products.map(p=>'<option value="'+p.id+'" '+(Number(c?.product_id)===Number(p.id)?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></label><label>Combo name<input id="comboName" value="'+esc(c?.name||'')+'" placeholder="e.g. Family Meal"></label><label class="wide">Description<textarea id="comboDesc">'+esc(c?.description||'')+'</textarea></label></div><div class="recipe-add-line"><select id="comboItem"><option value="">Choose menu item</option>'+restaurantCache.menuItems.map(x=>'<option value="'+x.id+'">'+esc(x.product_name)+'</option>').join('')+'</select><input id="comboQty" type="number" min="0.001" value="1"><button onclick="addComboItem()">Add Item</button></div><div id="comboDraft"></div><div class="builder-actions"><button class="secondary" onclick="comboManager()">Cancel</button><button onclick="saveCombo('+(id||'null')+')">Save Combo</button></div></div>';renderComboDraft()}
function addComboItem(){const id=Number($('comboItem').value);if(!id)return;const item=restaurantCache.menuItems.find(x=>Number(x.id)===id),existing=comboDraft.find(x=>x.menuItemId===id);if(existing)existing.qty+=Number($('comboQty').value||1);else comboDraft.push({menuItemId:id,name:item?.product_name||'',qty:Number($('comboQty').value||1),required:true});renderComboDraft()}
function renderComboDraft(){if(!$('comboDraft'))return;$('comboDraft').innerHTML=comboDraft.map((x,i)=>'<div class="draft-line"><span><b>'+esc(x.name)+'</b> × '+x.qty+'</span><button class="ghost" onclick="comboDraft.splice('+i+',1);renderComboDraft()">Remove</button></div>').join('')||'<div class="empty">Add combo components.</div>'}
async function saveCombo(id){if(!comboDraft.length)return showToast('Add combo items','warning');await api('/menu/combos',{method:'POST',body:JSON.stringify({id,productId:Number($('comboProduct').value),name:$('comboName').value,description:$('comboDesc').value,items:comboDraft})});showToast('Combo saved');comboManager()}

async function ingredientManager(){const [ings,units,locs]=await Promise.all([api('/ingredients'),api('/units'),api('/inventory/locations')]);ingredientCache=ings;unitCache=units;window._ingredientLocations=locs;const rows=ings.map(x=>'<tr><td><b>'+esc(x.name)+'</b><small>'+esc(x.sku||'')+'</small></td><td>'+esc(x.unit_symbol||'-')+'</td><td>'+Number(x.location_stock)+'</td><td>'+money(x.cost)+'</td><td>'+Number(x.reorder_level)+'</td><td class="right"><button class="secondary ing-edit" data-id="'+x.id+'">Edit</button></td></tr>').join('')||'<tr><td colspan="6">No ingredients registered.</td></tr>';$('view').innerHTML='<div class="panel"><div class="panel-head"><div><h3>Ingredients & Raw Materials</h3><p class="muted">Ingredients use the same controlled stock ledger as purchases, transfers, counts and wastage.</p></div><div class="action-row"><button class="secondary" onclick="inventory()">Back to Inventory</button><button class="secondary" onclick="unitManager()">Units</button><button onclick="ingredientForm()">+ Ingredient</button></div></div><div id="ingredientWork"></div><div class="table-wrap"><table><thead><tr><th>Ingredient</th><th>Base Unit</th><th>Total Stock</th><th>Cost</th><th>Reorder</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div></div>';document.querySelectorAll('.ing-edit').forEach(b=>b.addEventListener('click',()=>ingredientForm(Number(b.dataset.id))))}
async function ingredientForm(id=null){if(!unitCache.length)unitCache=await api('/units');const ing=id?ingredientCache.find(x=>Number(x.id)===Number(id)):null,locs=window._ingredientLocations||await api('/inventory/locations');$('ingredientWork').innerHTML='<div class="inventory-editor"><h4>'+(ing?'Edit Ingredient':'New Ingredient')+'</h4><div class="form-row"><label>Name<input id="ingName" value="'+esc(ing?.name||'')+'" placeholder="e.g. Tomatoes"></label><label>SKU<input id="ingSku" value="'+esc(ing?.sku||'')+'" placeholder="Optional code"></label><label>Base unit<select id="ingUnit">'+unitCache.map(u=>'<option value="'+u.id+'" '+(Number(ing?.base_unit_id)===Number(u.id)?'selected':'')+'>'+esc(u.name)+' ('+esc(u.symbol)+')</option>').join('')+'</select></label><label>Average / opening cost<input id="ingCost" type="number" min="0" step="0.01" value="'+Number(ing?.cost||0)+'"></label><label>Reorder level<input id="ingReorder" type="number" min="0" step="0.001" value="'+Number(ing?.reorder_level||0)+'"></label>'+(!ing?'<label>Opening stock<input id="ingOpening" type="number" min="0" step="0.001" value="0"></label><label>Opening location<select id="ingLocation">'+locs.map(l=>'<option value="'+l.id+'">'+esc(l.branch_name)+' · '+esc(l.name)+'</option>').join('')+'</select></label>':'')+'</div><div class="builder-actions"><button class="secondary" onclick="ingredientManager()">Cancel</button><button onclick="saveIngredient('+(ing?ing.id:'null')+')">'+(ing?'Update Ingredient':'Save Ingredient')+'</button></div></div>'}
async function saveIngredient(id){const body={name:$('ingName').value,sku:$('ingSku').value,baseUnitId:Number($('ingUnit').value),cost:Number($('ingCost').value||0),reorderLevel:Number($('ingReorder').value||0)};if(id){await api('/ingredients/'+id,{method:'PUT',body:JSON.stringify(body)});showToast('Ingredient updated')}else{body.openingStock=Number($('ingOpening').value||0);body.locationId=Number($('ingLocation').value||0)||null;await api('/ingredients',{method:'POST',body:JSON.stringify(body)});showToast('Ingredient created')}ingredientManager()}
async function unitManager(){const units=await api('/units');unitCache=units;const rows=units.map(u=>'<tr><td><b>'+esc(u.name)+'</b></td><td>'+esc(u.symbol)+'</td><td>'+esc(u.unit_type)+'</td><td>'+Number(u.base_factor)+'</td></tr>').join('');$('view').innerHTML='<div class="panel"><div class="panel-head"><div><h3>Units & Conversions</h3><p class="muted">Conversion factor is relative to the base family unit. Example: kg=1, g=0.001; L=1, ml=0.001.</p></div><button class="secondary" onclick="ingredientManager()">Back to Ingredients</button></div><div class="inline-form"><input id="uName" placeholder="Unit name"><input id="uSymbol" placeholder="Symbol"><select id="uType"><option value="count">Count</option><option value="weight">Weight</option><option value="volume">Volume</option></select><input id="uFactor" type="number" min="0.000001" step="0.000001" value="1" placeholder="Conversion factor"><button onclick="saveUnit()">Add Unit</button></div><div class="table-wrap"><table><thead><tr><th>Unit</th><th>Symbol</th><th>Type</th><th>Base Factor</th></tr></thead><tbody>'+rows+'</tbody></table></div></div>'}
async function saveUnit(){await api('/units',{method:'POST',body:JSON.stringify({name:$('uName').value,symbol:$('uSymbol').value,unitType:$('uType').value,baseFactor:Number($('uFactor').value)})});showToast('Unit added');unitManager()}
async function recipeManager(){const recipes=await api('/recipes');const rows=recipes.map(r=>{const perYield=Number(r.recipe_cost)/Math.max(1,Number(r.yield_qty));const foodPct=Number(r.price)>0?(perYield/Number(r.price)*100):0;return '<tr><td><b>'+esc(r.product_name)+'</b><small>'+esc(r.name)+'</small></td><td>'+Number(r.yield_qty)+'</td><td>'+Number(r.line_count)+'</td><td>'+esc(r.consumption_location||'Automatic')+'</td><td>'+money(perYield)+'</td><td>'+foodPct.toFixed(1)+'%</td><td class="right"><button class="secondary recipe-edit" data-id="'+r.id+'">Edit</button> <button class="ghost recipe-archive" data-id="'+r.id+'">Archive</button></td></tr>'}).join('')||'<tr><td colspan="7">No recipes configured.</td></tr>';$('view').innerHTML='<div class="panel"><div class="panel-head"><div><h3>Recipes / BOM</h3><p class="muted">Define exact ingredient quantities per menu item. Sales automatically consume these ingredients.</p></div><div class="action-row"><button class="secondary" onclick="inventory()">Back to Inventory</button><button onclick="recipeForm()">+ Recipe</button></div></div><div id="recipeWork"></div><div class="table-wrap"><table><thead><tr><th>Menu Item</th><th>Yield</th><th>Ingredients</th><th>Stock Location</th><th>Cost / Portion</th><th>Food Cost %</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div></div>';document.querySelectorAll('.recipe-edit').forEach(b=>b.addEventListener('click',()=>recipeForm(Number(b.dataset.id))));document.querySelectorAll('.recipe-archive').forEach(b=>b.addEventListener('click',()=>archiveRecipe(Number(b.dataset.id))))}
async function recipeForm(id=null){const [products,ings,units,locs,detail]=await Promise.all([api('/products'),api('/ingredients'),api('/units'),api('/inventory/locations'),id?api('/recipes/'+id):Promise.resolve(null)]);recipeIngredients=ings;recipeUnits=units;recipeLocations=locs;recipeLineDraft=detail?detail.lines.map(x=>({ingredientProductId:Number(x.ingredient_product_id),ingredientName:x.ingredient_name,quantity:Number(x.quantity),unitId:Number(x.unit_id),wastePercent:Number(x.waste_percent)})):[];const r=detail?.recipe;$('recipeWork').innerHTML='<div class="inventory-editor"><h4>'+(id?'Edit Recipe':'New Recipe')+'</h4><div class="form-row"><label>Menu product<select id="recipeProduct">'+products.map(p=>'<option value="'+p.id+'" '+(Number(r?.product_id)===Number(p.id)?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></label><label>Recipe name<input id="recipeName" value="'+esc(r?.name||'')+'" placeholder="e.g. Beef Burger Standard"></label><label>Yield / portions<input id="recipeYield" type="number" min="0.001" step="0.001" value="'+Number(r?.yield_qty||1)+'"></label><label>Consume stock from<select id="recipeLocation"><option value="">Automatic kitchen/default</option>'+locs.map(l=>'<option value="'+l.id+'" '+(Number(r?.consumption_location_id)===Number(l.id)?'selected':'')+'>'+esc(l.branch_name)+' · '+esc(l.name)+'</option>').join('')+'</select></label></div><div class="recipe-add-line"><select id="recipeIngredient"><option value="">Choose ingredient</option>'+ings.map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join('')+'</select><input id="recipeQty" type="number" min="0.000001" step="0.001" placeholder="Quantity"><select id="recipeUnit">'+units.map(u=>'<option value="'+u.id+'">'+esc(u.symbol)+' · '+esc(u.name)+'</option>').join('')+'</select><input id="recipeWaste" type="number" min="0" step="0.1" value="0" placeholder="Waste %"><button onclick="addRecipeLine()">Add Ingredient</button></div><div id="recipeLines"></div><div class="builder-actions"><button class="secondary" onclick="recipeManager()">Cancel</button><button onclick="saveRecipe()">Save Recipe</button></div></div>';renderRecipeLines()}
function addRecipeLine(){const iid=Number($('recipeIngredient').value),qty=Number($('recipeQty').value),uid=Number($('recipeUnit').value);if(!iid||!(qty>0)||!uid)return showToast('Choose an ingredient, quantity and unit','warning');const ing=recipeIngredients.find(x=>Number(x.id)===iid),existing=recipeLineDraft.find(x=>x.ingredientProductId===iid);const line={ingredientProductId:iid,ingredientName:ing?.name||'',quantity:qty,unitId:uid,wastePercent:Number($('recipeWaste').value||0)};if(existing)Object.assign(existing,line);else recipeLineDraft.push(line);renderRecipeLines()}
function renderRecipeLines(){if(!$('recipeLines'))return;const rows=recipeLineDraft.map((x,i)=>'<tr><td><b>'+esc(x.ingredientName)+'</b></td><td><input class="mini-input" type="number" min="0.000001" step="0.001" value="'+x.quantity+'" onchange="recipeLineDraft['+i+'].quantity=Number(this.value)"></td><td><select class="mini-input" onchange="recipeLineDraft['+i+'].unitId=Number(this.value)">'+recipeUnits.map(u=>'<option value="'+u.id+'" '+(Number(u.id)===Number(x.unitId)?'selected':'')+'>'+esc(u.symbol)+'</option>').join('')+'</select></td><td><input class="mini-input" type="number" min="0" step="0.1" value="'+x.wastePercent+'" onchange="recipeLineDraft['+i+'].wastePercent=Number(this.value)"></td><td><button class="ghost" onclick="recipeLineDraft.splice('+i+',1);renderRecipeLines()">Remove</button></td></tr>').join('');$('recipeLines').innerHTML=recipeLineDraft.length?'<div class="table-wrap"><table><thead><tr><th>Ingredient</th><th>Qty</th><th>Unit</th><th>Waste %</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div>':'<div class="empty">Add at least one ingredient to the recipe.</div>'}
async function saveRecipe(){if(!recipeLineDraft.length)return showToast('Add at least one ingredient','warning');await api('/recipes',{method:'POST',body:JSON.stringify({productId:Number($('recipeProduct').value),name:$('recipeName').value,yieldQty:Number($('recipeYield').value),consumptionLocationId:Number($('recipeLocation').value)||null,lines:recipeLineDraft})});showToast('Recipe saved');recipeManager()}
async function archiveRecipe(id){const r=await appPrompt({title:'Archive Recipe',message:'The menu item will stop consuming this recipe until another active recipe is saved.',placeholder:'Optional note',confirmText:'Archive'});if(!r)return;await api('/recipes/'+id,{method:'DELETE'});showToast('Recipe archived');recipeManager()}
async function consumptionForm(){const [items,locs]=await Promise.all([api('/inventory/items'),api('/inventory/locations')]);$('view').innerHTML='<div class="panel"><div class="panel-head"><div><h3>Staff Meals & Complimentary Items</h3><p class="muted">Record non-sale consumption. If the selected menu item has a recipe, its ingredients are deducted automatically.</p></div><button class="secondary" onclick="inventory()">Back to Inventory</button></div><div class="inventory-editor"><div class="form-row"><label>Type<select id="consType"><option value="staff_meal">Staff Meal</option><option value="complimentary">Complimentary / FOC</option></select></label><label>Item<select id="consProduct">'+items.map(x=>'<option value="'+x.id+'">'+esc(x.name)+(x.item_type==='ingredient'?' · ingredient':'')+'</option>').join('')+'</select></label><label>Quantity / portions<input id="consQty" type="number" min="0.001" step="0.001" value="1"></label><label>Stock location<select id="consLocation"><option value="">Recipe / automatic location</option>'+locs.map(l=>'<option value="'+l.id+'">'+esc(l.branch_name)+' · '+esc(l.name)+'</option>').join('')+'</select></label><label class="wide">Notes<textarea id="consNotes" placeholder="Reason / staff member / complimentary authorization"></textarea></label></div><div class="builder-actions"><button onclick="recordConsumption()">Record Consumption</button></div></div></div>'}
async function recordConsumption(){await api('/inventory/consumptions',{method:'POST',body:JSON.stringify({consumptionType:$('consType').value,productId:Number($('consProduct').value),qty:Number($('consQty').value),locationId:Number($('consLocation').value)||null,notes:$('consNotes').value})});showToast('Consumption posted to stock ledger');inventory()}

async function suppliers(){const rows=await api('/suppliers');$('view').innerHTML=`<div class="panel"><div class="panel-head"><h3>Suppliers</h3><button onclick="supplierForm()">+ Add supplier</button></div><div id="form"></div><div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Phone</th><th>Email</th><th>Products supplied</th><th class="right">Balance</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td><b>${esc(s.name)}</b></td><td>${esc(s.phone||'-')}</td><td>${esc(s.email||'-')}</td><td>${(s.products||[]).map(p=>`<span class="pill">${esc(p.name)}</span>`).join(' ')||'<span class="muted">No products assigned</span>'}</td><td class="right">${money(s.balance)}</td><td class="right"><button class="secondary" onclick="manageSupplierProducts(${s.id},'${esc(s.name).replace(/'/g,"&#39;")}')">Products</button></td></tr>`).join('')}</tbody></table></div></div>`}
async function supplierForm(){const ps=await api('/inventory/items');$('form').innerHTML=`<div class="inline-form"><input id="sn" placeholder="Supplier name"><input id="sph" placeholder="Phone"><input id="sem" type="email" placeholder="Email"><div class="selection-box"><b>Products this supplier supplies</b><small>Only selected products will be available for this supplier in purchasing/receiving.</small><div class="check-grid">${ps.map(p=>`<label><input type="checkbox" data-supplier-product="${p.id}"> ${esc(p.name)}${p.sku?' - '+esc(p.sku):''}</label>`).join('')||'<span class="muted">Create products first, or save the supplier and assign them later.</span>'}</div></div><button onclick="saveSupplier()">Save supplier</button></div>`}
async function saveSupplier(){const productIds=[...document.querySelectorAll('[data-supplier-product]:checked')].map(x=>Number(x.dataset.supplierProduct));await api('/suppliers',{method:'POST',body:JSON.stringify({name:$('sn').value,phone:$('sph').value,email:$('sem').value,productIds})});suppliers()}
async function manageSupplierProducts(id,name){const [ps,sups]=await Promise.all([api('/inventory/items'),api('/suppliers')]),s=sups.find(x=>Number(x.id)===Number(id)),chosen=new Set((s?.products||[]).map(x=>Number(x.id)));$('form').innerHTML=`<div class="relation-editor"><div><h4>${esc(name)} - Products supplied</h4><p class="muted">Purchasing will only show products selected here when this supplier is chosen.</p></div><div class="check-grid">${ps.map(p=>`<label><input type="checkbox" data-edit-supplier-product="${p.id}" ${chosen.has(Number(p.id))?'checked':''}> ${esc(p.name)}${p.sku?' - '+esc(p.sku):''}</label>`).join('')||'<span class="muted">No products registered.</span>'}</div><button onclick="saveSupplierProducts(${id})">Save product list</button></div>`}
async function saveSupplierProducts(id){const productIds=[...document.querySelectorAll('[data-edit-supplier-product]:checked')].map(x=>Number(x.dataset.editSupplierProduct));await api('/suppliers/'+id+'/products',{method:'PUT',body:JSON.stringify({productIds})});suppliers()}
async function people(type,label){const rows=await api('/'+type);$('view').innerHTML=`<div class="panel"><div class="panel-head"><h3>${label}s</h3><button onclick="personForm('${type}','${label}')">+ Add ${label}</button></div><div id="form"></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Phone</th><th>Email</th><th class="right">Balance</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.phone)}</td><td>${esc(x.email)}</td><td class="right">${money(x.balance)}</td></tr>`).join('')}</tbody></table></div></div>`}
function personForm(type,label){$('form').innerHTML=`<div class="inline-form"><input id="n" placeholder="${label} name"><input id="ph" placeholder="Phone"><input id="em" placeholder="Email"><button onclick="savePerson('${type}','${label}')">Save</button></div>`}
async function savePerson(type,label){await api('/'+type,{method:'POST',body:JSON.stringify({name:$('n').value,phone:$('ph').value,email:$('em').value})});people(type,label)}

let poDraft={supplierId:null,branchId:null,items:[]},supplierProductsCache=[];
async function purchasing(){const [o,pos,grns,moves]=await Promise.all([api('/purchasing/overview'),api('/purchase-orders'),api('/grns'),api('/stock-movements')]);let poRows=pos.map(x=>'<tr><td><b>'+esc(x.po_no)+'</b><small>'+esc(x.branch_name||'')+'</small></td><td>'+esc(x.supplier_name)+'</td><td><span class="pill">'+esc(x.status)+'</span></td><td>'+Number(x.received_qty)+'/'+Number(x.total_qty)+'</td><td>'+money(x.total)+'</td><td class="right">'+(['draft','rejected'].includes(x.status)?'<button class="secondary" onclick="submitPO('+x.id+')">'+(x.status==='rejected'?'Resubmit':'Submit for Approval')+'</button>':'')+(['ordered','partial'].includes(x.status)?' <button onclick="receivePO('+x.id+')">Receive</button>':'')+' <button class="secondary" onclick="openPdf(\'/documents/purchase-order/'+x.id+'/pdf\')">PDF</button>'+'</td></tr>').join('')||'<tr><td colspan="6">No purchase orders yet.</td></tr>';let grnRows=grns.slice(0,12).map(x=>'<tr><td><b>'+esc(x.grn_no)+'</b><small>'+new Date(x.received_at).toLocaleString()+'</small></td><td>'+esc(x.supplier_name)+'</td><td>'+esc(x.po_no)+'</td><td>'+money(x.total)+'</td></tr>').join('')||'<tr><td colspan="4">No GRNs yet.</td></tr>';let moveRows=moves.slice(0,20).map(x=>'<tr><td>'+new Date(x.created_at).toLocaleString()+'</td><td>'+esc(x.product_name)+'</td><td><span class="pill">'+esc(x.movement_type)+'</span></td><td>'+esc(x.reference_no||'-')+'</td><td>+'+Number(x.quantity)+'</td><td>'+Number(x.stock_before)+'</td><td><b>'+Number(x.stock_after)+'</b></td></tr>').join('')||'<tr><td colspan="7">No stock movements yet.</td></tr>';$('view').innerHTML='<div class="kpi-grid purchase-kpis">'+card('Open POs',o.openOrders,'Draft, ordered & partial','blue')+card('Purchase Value',money(o.purchaseValueMonth),'Current month','purple')+card('GRNs Today',o.receiptsToday,'Goods received','green')+card('Low Stock',o.lowStock,'Requires attention',o.lowStock?'red':'')+'</div><div class="panel"><div class="panel-head"><div><h3>Purchasing & Receiving</h3><p class="muted">Create supplier-filtered purchase orders, receive against them, and update stock through GRNs.</p></div><button onclick="newPurchaseOrder()">+ New Purchase Order</button></div><div id="purchaseWork"></div></div><div class="two-col"><div class="panel"><h3>Purchase Orders</h3><div class="table-wrap"><table><thead><tr><th>PO</th><th>Supplier</th><th>Status</th><th>Qty</th><th>Total</th><th></th></tr></thead><tbody>'+poRows+'</tbody></table></div></div><div class="panel"><h3>Recent GRNs</h3><div class="table-wrap"><table><thead><tr><th>GRN</th><th>Supplier</th><th>PO</th><th>Total</th></tr></thead><tbody>'+grnRows+'</tbody></table></div></div></div><div class="panel"><h3>Recent Stock Movements</h3><div class="table-wrap"><table><thead><tr><th>Date</th><th>Product</th><th>Type</th><th>Reference</th><th>Qty</th><th>Before</th><th>After</th></tr></thead><tbody>'+moveRows+'</tbody></table></div></div>';bindPdfLinks()}
async function newPurchaseOrder(){const [sups,branches]=await Promise.all([api('/suppliers'),api('/branches')]);poDraft={supplierId:null,branchId:branches[0]?.id||null,items:[]};$('purchaseWork').innerHTML='<div class="po-builder"><div class="form-row"><label>Supplier<select id="poSupplier" onchange="loadSupplierProducts()"><option value="">Choose supplier</option>'+sups.map(s=>'<option value="'+s.id+'">'+esc(s.name)+'</option>').join('')+'</select></label><label>Branch<select id="poBranch">'+branches.map(b=>'<option value="'+b.id+'">'+esc(b.name)+'</option>').join('')+'</select></label></div><div id="poProducts" class="muted">Choose a supplier to see only products registered for that supplier.</div><div id="poLines"></div><textarea id="poNotes" placeholder="Purchase notes (optional)"></textarea><div class="builder-actions"><button class="secondary" onclick="purchasing()">Cancel</button><button class="secondary" onclick="previewPO()">Preview</button><button onclick="savePO()">Save Draft PO</button></div></div>'}
async function loadSupplierProducts(){const sid=Number($('poSupplier').value);poDraft.supplierId=sid||null;poDraft.items=[];supplierProductsCache=[];renderPOLines();if(!sid){$('poProducts').innerHTML='<span class="muted">Choose a supplier to see products.</span>';return}const d=await api('/suppliers/'+sid+'/products');supplierProductsCache=d.products||[];$('poProducts').innerHTML='<div class="supplier-products"><div><b>'+esc(d.supplier.name)+' products</b><small>Only registered products are available.</small></div><div class="product-grid">'+(supplierProductsCache.map(p=>'<button class="product-tile" data-po-product="'+p.id+'"><b>'+esc(p.name)+'</b><span>'+(p.sku?esc(p.sku):'No SKU')+'</span><small>Current stock '+Number(p.stock)+'</small></button>').join('')||'<div class="empty">No products are registered for this supplier.</div>')+'</div></div>';document.querySelectorAll('[data-po-product]').forEach(btn=>btn.addEventListener('click',()=>addPOItemFromSupplier(Number(btn.dataset.poProduct))))}
function addPOItemFromSupplier(productId){const p=supplierProductsCache.find(x=>Number(x.id)===Number(productId));if(!p)return;addPOItem(Number(p.id),p.name,Number(p.supplier_price??p.cost??0))}
function addPOItem(productId,name,unitCost){const x=poDraft.items.find(i=>i.productId===productId);if(x)x.qty++;else poDraft.items.push({productId,name,qty:1,unitCost:Number(unitCost||0)});renderPOLines()}
function renderPOLines(){if(!$('poLines'))return;if(!poDraft.items.length){$('poLines').innerHTML='<div class="empty">No products added to this purchase order.</div>';return}const rows=poDraft.items.map((x,i)=>'<tr><td><b>'+esc(x.name)+'</b></td><td><input class="mini-input" type="number" min="0.001" step="0.001" value="'+x.qty+'" onchange="poDraft.items['+i+'].qty=Number(this.value);renderPOLines()"></td><td><input class="mini-input" type="number" min="0" value="'+x.unitCost+'" onchange="poDraft.items['+i+'].unitCost=Number(this.value);renderPOLines()"></td><td>'+money(x.qty*x.unitCost)+'</td><td><button class="ghost" onclick="poDraft.items.splice('+i+',1);renderPOLines()">Remove</button></td></tr>').join('');$('poLines').innerHTML='<div class="table-wrap"><table><thead><tr><th>Product</th><th>Qty</th><th>Unit Cost</th><th>Total</th><th></th></tr></thead><tbody>'+rows+'</tbody></table><div class="po-total"><span>Total</span><strong>'+money(poDraft.items.reduce((n,x)=>n+x.qty*x.unitCost,0))+'</strong></div></div>'}
async function previewPO(){if(!poDraft.supplierId)return alert('Choose a supplier');if(!poDraft.items.length)return alert('Add at least one product');const s=(await api('/suppliers')).find(x=>Number(x.id)===Number(poDraft.supplierId));const total=poDraft.items.reduce((n,x)=>n+x.qty*x.unitCost,0);previewDocument('PURCHASE ORDER','Draft',{Supplier:s?.name||'',Branch:$('poBranch').options[$('poBranch').selectedIndex]?.text||'',Notes:$('poNotes').value||'-'},poDraft.items.map(x=>({name:x.name,qty:x.qty,unit:Number(x.unitCost).toLocaleString(),total:Number(x.qty*x.unitCost).toLocaleString()})),total)}
async function savePO(){if(!poDraft.supplierId)return alert('Choose a supplier');if(!poDraft.items.length)return alert('Add at least one product');await api('/purchase-orders',{method:'POST',body:JSON.stringify({supplierId:poDraft.supplierId,branchId:Number($('poBranch').value)||null,notes:$('poNotes').value,items:poDraft.items.map(x=>({productId:x.productId,qty:x.qty,unitCost:x.unitCost}))})});purchasing()}
async function submitPO(id){const r=await appPrompt({title:'Submit Purchase Order for Approval',message:'Add a note for the approving supervisor. You can also flag the request as urgent.',placeholder:'e.g. Needed urgently for tomorrow\'s service',urgent:true,confirmText:'Submit for Approval'});if(!r)return;await api('/purchase-orders/'+id+'/submit',{method:'POST',body:JSON.stringify({comment:r.comment,urgent:r.urgent})});showToast(r.urgent?'Urgent approval request submitted':'Purchase order submitted for approval');purchasing()}
async function receivePO(id){const d=await api('/purchase-orders/'+id);const rows=d.items.map(x=>{const out=Number(x.qty_ordered)-Number(x.qty_received);return '<tr><td><b>'+esc(x.product_name)+'</b></td><td>'+Number(x.qty_ordered)+'</td><td>'+Number(x.qty_received)+'</td><td>'+out+'</td><td><input class="mini-input receive-qty" data-item="'+x.id+'" type="number" min="0" max="'+out+'" step="0.001" value="'+out+'"></td><td><input class="mini-input receive-cost" data-item="'+x.id+'" type="number" min="0" value="'+Number(x.unit_cost)+'"></td></tr>'}).join('');$('purchaseWork').innerHTML='<div class="receipt-builder"><div class="panel-head"><div><h3>Receive '+esc(d.order.po_no)+'</h3><p class="muted">'+esc(d.order.supplier_name)+' · Receive only outstanding quantities.</p></div></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Ordered</th><th>Received</th><th>Outstanding</th><th>Receive Now</th><th>Unit Cost</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="form-row"><label>Supplier reference<input id="grnSupplierRef" placeholder="Invoice / delivery note"></label><label>Receiving notes<input id="grnNotes" placeholder="Optional notes"></label></div><div class="builder-actions"><button class="secondary" onclick="purchasing()">Cancel</button><button onclick="saveReceipt('+id+')">Post GRN & Update Stock</button></div></div>'}
async function saveReceipt(id){const items=[...document.querySelectorAll('.receive-qty')].map(q=>({itemId:Number(q.dataset.item),qty:Number(q.value),unitCost:Number(document.querySelector('.receive-cost[data-item="'+q.dataset.item+'"]').value)})).filter(x=>x.qty>0);if(!items.length)return alert('Enter at least one received quantity');await api('/purchase-orders/'+id+'/receive',{method:'POST',body:JSON.stringify({items,supplierReference:$('grnSupplierRef').value,notes:$('grnNotes').value})});purchasing()}

async function expenses(){const rows=await api('/expenses');$('view').innerHTML='<div class="panel"><div class="panel-head"><div><h3>Expenses & Cost Register</h3><p class="muted">Manual operating expenses and automatically reconciled costs from system transactions.</p></div><button onclick="expenseForm()">+ Record manual expense</button></div><div id="form"></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Date</th><th>Category</th><th>Description</th><th>Source</th><th>Treatment</th><th class="right">Amount</th><th></th></tr></thead><tbody>'+rows.map(x=>'<tr><td><b>'+esc(x.reference_no||('EXP-'+x.id))+'</b></td><td>'+esc(x.expense_date).slice(0,10)+'</td><td>'+esc(x.category)+'</td><td>'+esc(x.description)+(x.supplier_name?'<small>'+esc(x.supplier_name)+'</small>':'')+'</td><td>'+(x.auto_generated?'<span class="pill">Auto · '+esc(x.source_type||'System')+'</span>':'<span class="pill">Manual</span>')+'</td><td>'+esc(String(x.accounting_treatment||'operating_expense').replaceAll('_',' '))+'</td><td class="right">'+money(x.amount)+'</td><td class="right"><button class="secondary pdf-link" data-pdf="/documents/expense/'+x.id+'/pdf">PDF</button></td></tr>').join('')+'</tbody></table></div></div>';bindPdfLinks()}
function expenseForm(){$('form').innerHTML='<div class="inline-form"><input id="ec" placeholder="Category"><input id="ed" placeholder="Description"><input id="ea" type="number" min="0" placeholder="Amount"><input id="eDate" type="date"><div class="builder-actions"><button class="secondary" onclick="previewExpense()">Preview</button><button onclick="saveExpense()">Save Expense</button></div></div>'}
function previewExpense(){const amount=Number($('ea').value||0);if(!$('ed').value.trim()||amount<=0)return alert('Enter description and amount');previewDocument('EXPENSE / COST VOUCHER','Draft',{Category:$('ec').value||'General',Date:$('eDate').value||new Date().toISOString().slice(0,10),Source:'Manual'},[{name:$('ed').value,qty:'',unit:'',total:amount.toLocaleString()}],amount)}
async function saveExpense(){await api('/expenses',{method:'POST',body:JSON.stringify({category:$('ec').value,description:$('ed').value,amount:$('ea').value,expenseDate:$('eDate').value||null})});expenses()}
let currentRestaurantOrder=null,currentOrderMenu=[],currentOrderModifierGroups=[];
async function orders(){const [rows,tables,reservations]=await Promise.all([api('/restaurant/orders?status=active'),api('/restaurant/tables'),api('/restaurant/reservations')]);const cards=rows.map(o=>'<div class="order-card '+(o.held?'held':'')+'"><div class="order-card-head"><div><b>'+esc(o.order_no)+'</b><small>'+esc(o.order_type.replaceAll('_',' '))+(o.table_name?' · '+esc(o.table_name):'')+'</small></div><span class="pill">'+esc(o.status.replaceAll('_',' '))+'</span></div><div class="order-card-meta"><span>'+o.guest_count+' guests</span><span>'+esc(o.waiter_name||'No waiter')+'</span><strong>'+money(o.total)+'</strong></div><button class="open-order" data-id="'+o.id+'">'+(o.held?'Resume / Open':'Open Order')+'</button></div>').join('')||'<div class="empty">No open restaurant orders.</div>';const resRows=reservations.slice(0,10).map(r=>'<tr><td>'+new Date(r.reserved_at).toLocaleString()+'</td><td><b>'+esc(r.guest_name||r.customer_name||'Guest')+'</b><small>'+esc(r.phone||'')+'</small></td><td>'+r.guest_count+'</td><td>'+esc(r.table_name||'Unassigned')+'</td><td><span class="pill">'+esc(r.status)+'</span></td></tr>').join('')||'<tr><td colspan="5">No upcoming reservations.</td></tr>';$('view').innerHTML='<div class="panel"><div class="panel-head"><div><h3>Restaurant Orders</h3><p class="muted">Open tables, tabs, takeaway and delivery orders. Orders remain editable until sent to kitchen.</p></div><div class="action-row"><button class="secondary" onclick="cancelledRestaurantOrders()">Cancelled</button><button class="secondary" onclick="reservationManager()">Reservations</button><button onclick="newRestaurantOrderForm()">+ New Order</button></div></div><div id="orderWork"></div><div class="order-card-grid">'+cards+'</div></div><div class="panel"><h3>Upcoming Reservations</h3><div class="table-wrap"><table><thead><tr><th>Time</th><th>Guest</th><th>Covers</th><th>Table</th><th>Status</th></tr></thead><tbody>'+resRows+'</tbody></table></div></div>';document.querySelectorAll('.open-order').forEach(b=>b.addEventListener('click',()=>openRestaurantOrder(Number(b.dataset.id))))}
async function newRestaurantOrderForm(){const [branches,tables,staff,customers,reservations]=await Promise.all([api('/branches'),api('/restaurant/tables'),api('/staff'),api('/customers'),api('/restaurant/reservations')]);$('orderWork').innerHTML='<div class="inventory-editor"><h4>Open Restaurant Order</h4><div class="form-row"><label>Order type<select id="ordType"><option value="dine_in">Dine-in</option><option value="takeaway">Takeaway</option><option value="delivery">Delivery</option><option value="counter">Counter</option></select></label><label>Branch<select id="ordBranch">'+branches.map(b=>'<option value="'+b.id+'">'+esc(b.name)+'</option>').join('')+'</select></label><label>Table<select id="ordTable"><option value="">No table</option>'+tables.filter(t=>['available','reserved'].includes(t.status)).map(t=>'<option value="'+t.id+'">'+esc(t.area_name||'')+' · '+esc(t.name)+' ('+t.capacity+')</option>').join('')+'</select></label><label>Guests / Covers<input id="ordGuests" type="number" min="1" value="1"></label><label>Waiter<select id="ordWaiter"><option value="">Unassigned</option>'+staff.map(s=>'<option value="'+s.id+'">'+esc(s.name)+' · '+esc(s.role)+'</option>').join('')+'</select></label><label>Customer<select id="ordCustomer"><option value="">Walk-in</option>'+customers.map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join('')+'</select></label><label>Reservation<select id="ordReservation"><option value="">None</option>'+reservations.filter(r=>r.status==='reserved').map(r=>'<option value="'+r.id+'">'+new Date(r.reserved_at).toLocaleString()+' · '+esc(r.guest_name||r.customer_name||'Guest')+'</option>').join('')+'</select></label><label class="wide">Order notes<textarea id="ordNotes" placeholder="Guest or service notes"></textarea></label></div><div class="builder-actions"><button class="secondary" onclick="orders()">Cancel</button><button onclick="createRestaurantOrder()">Open Order</button></div></div>';const sync=()=>{$('ordTable').disabled=$('ordType').value!=='dine_in'};$('ordType').addEventListener('change',sync);sync()}
async function createRestaurantOrder(){const type=$('ordType').value,tableId=Number($('ordTable').value)||null;if(type==='dine_in'&&!tableId)return showToast('Choose a table for dine-in','warning');const o=await api('/restaurant/orders',{method:'POST',body:JSON.stringify({branchId:Number($('ordBranch').value),orderType:type,tableId,reservationId:Number($('ordReservation').value)||null,customerId:Number($('ordCustomer').value)||null,guestCount:Number($('ordGuests').value),waiterUserId:Number($('ordWaiter').value)||null,notes:$('ordNotes').value})});showToast('Order opened');openRestaurantOrder(Number(o.id))}
async function openRestaurantOrder(id){const d=await api('/restaurant/orders/'+id);currentRestaurantOrder=d;currentOrderMenu=await api('/menu/available?branchId='+d.order.branch_id+'&orderType='+encodeURIComponent(d.order.order_type));currentOrderModifierGroups=await api('/menu/modifier-groups');const itemRows=d.items.map(x=>'<div class="ticket-item"><div><b>'+esc(x.product_name)+(x.variant_name?' · '+esc(x.variant_name):'')+'</b><small>'+esc(x.notes||'')+'</small>'+((x.modifiers||[]).length?'<small>'+x.modifiers.map(m=>esc(m.name)+(Number(m.price)?' +'+money(m.price):'')).join(', ')+'</small>':'')+'</div><div class="ticket-qty">'+Number(x.qty)+'</div><div class="ticket-price">'+money(Number(x.line_total)+(x.modifiers||[]).reduce((n,m)=>n+Number(m.price||0)*Number(m.qty||1),0))+'</div>'+(['open'].includes(d.order.status)?'<div><button class="ghost item-edit" data-id="'+x.id+'" data-qty="'+x.qty+'">Qty</button> <button class="ghost item-remove" data-id="'+x.id+'">Remove</button></div>':'')+'</div>').join('')||'<div class="empty">No items yet.</div>';const nextMap={open:['sent_to_kitchen','Send to Kitchen'],sent_to_kitchen:['preparing','Start Preparing'],preparing:['ready','Mark Ready'],ready:['served','Mark Served'],served:['bill_requested','Request Bill'],bill_requested:['partially_paid','Partially Paid'],partially_paid:['paid','Mark Paid'],paid:['closed','Close Order']},next=nextMap[d.order.status];$('view').innerHTML='<div class="order-editor"><div class="panel menu-pane"><div class="panel-head"><div><h3>'+esc(d.order.order_no)+'</h3><p class="muted">'+esc(d.order.order_type.replaceAll('_',' '))+(d.order.table_name?' · '+esc(d.order.table_name):'')+' · '+d.order.guest_count+' guests</p></div><span class="pill">'+esc(d.order.status.replaceAll('_',' '))+(d.order.held?' · held':'')+'</span></div><div class="pos-categories" id="orderCategories"></div><div class="product-grid" id="orderMenu"></div></div><div class="panel ticket-pane"><div class="panel-head"><div><h3>Order Ticket</h3><p class="muted">'+esc(d.order.waiter_name||'No waiter assigned')+'</p></div><button class="secondary" onclick="orders()">Back</button></div><div class="ticket-items">'+itemRows+'</div><div class="ticket-total"><span>Subtotal</span><strong>'+money(d.order.subtotal)+'</strong></div><div class="ticket-total grand"><span>Total</span><strong>'+money(d.order.total)+'</strong></div><div class="order-actions">'+(d.order.held?'<button onclick="resumeRestaurantOrder('+id+')">Resume</button>':'<button class="secondary" onclick="holdRestaurantOrder('+id+')">Hold</button>')+'<button class="secondary" onclick="transferRestaurantOrder('+id+')">Transfer</button><button class="secondary" onclick="mergeRestaurantOrder('+id+')">Merge</button><button class="secondary" onclick="splitRestaurantOrder('+id+')">Split</button>'+(next?'<button class="next-order-status" data-id="'+id+'" data-status="'+next[0]+'">'+next[1]+'</button>':'')+'</div><div class="order-history"><h4>History</h4>'+d.history.slice(0,8).map(h=>'<div><span>'+new Date(h.created_at).toLocaleString()+'</span><b>'+esc(h.to_status.replaceAll('_',' '))+'</b><small>'+esc(h.comment||h.changed_by||'')+'</small></div>').join('')+'</div></div></div>';renderOrderMenu();document.querySelectorAll('.item-edit').forEach(b=>b.addEventListener('click',()=>editOrderItemQty(id,Number(b.dataset.id),Number(b.dataset.qty))));document.querySelectorAll('.item-remove').forEach(b=>b.addEventListener('click',()=>removeRestaurantOrderItem(id,Number(b.dataset.id))));document.querySelectorAll('.next-order-status').forEach(b=>b.addEventListener('click',()=>transitionRestaurantOrder(Number(b.dataset.id),b.dataset.status)))}
function renderOrderMenu(category='all'){const cats=[...new Set(currentOrderMenu.map(x=>x.category_name||'Other'))];$('orderCategories').innerHTML='<button class="'+(category==='all'?'active':'')+'" data-cat="all">All</button>'+cats.map(c=>'<button class="'+(category===c?'active':'')+'" data-cat="'+esc(c)+'">'+esc(c)+'</button>').join('');$('orderMenu').innerHTML=currentOrderMenu.filter(x=>category==='all'||(x.category_name||'Other')===category).map(p=>'<button class="product-tile order-menu-item" data-product="'+p.id+'" data-menu="'+(p.menu_item_id||'')+'"><b>'+esc(p.name)+'</b><span>'+money(p.resolved_price)+'</span><small>'+esc(p.category_name||'Other')+'</small></button>').join('')||'<div class="empty">No menu items available.</div>';document.querySelectorAll('#orderCategories [data-cat]').forEach(b=>b.addEventListener('click',()=>renderOrderMenu(b.dataset.cat)));document.querySelectorAll('.order-menu-item').forEach(b=>b.addEventListener('click',()=>restaurantItemOptions(Number(b.dataset.product),Number(b.dataset.menu)||null)))}
async function restaurantItemOptions(productId,menuItemId){const p=currentOrderMenu.find(x=>Number(x.id)===productId);if(!p)return;let detail=null;if(menuItemId)detail=await api('/menu/items/'+menuItemId);const groups=(detail?.modifierGroupIds||[]).map(id=>currentOrderModifierGroups.find(g=>Number(g.id)===Number(id))).filter(Boolean);const overlay=document.createElement('div');overlay.className='app-modal-overlay';overlay.innerHTML='<div class="app-modal"><div class="app-modal-head"><div><h3>'+esc(p.name)+'</h3><p>'+money(p.resolved_price)+'</p></div><button class="app-modal-x">×</button></div><div class="app-modal-body"><label class="modal-label">Quantity<input id="oiQty" type="number" min="1" step="1" value="1"></label>'+(detail?.variants?.length?'<label class="modal-label">Variant<select id="oiVariant"><option value="">Standard</option>'+detail.variants.map(v=>'<option value="'+v.id+'">'+esc(v.name)+' '+(Number(v.price_delta)?(Number(v.price_delta)>0?'+':'')+money(v.price_delta):'')+'</option>').join('')+'</select></label>':'')+groups.map(g=>'<div class="modifier-select"><b>'+esc(g.name)+(g.required?' *':'')+'</b><small>Choose '+g.min_select+'–'+g.max_select+'</small>'+g.modifiers.map(m=>'<label><input type="checkbox" class="oi-mod" data-group="'+g.id+'" value="'+m.id+'"> '+esc(m.name)+(Number(m.price)?' +'+money(m.price):'')+'</label>').join('')+'</div>').join('')+'<label class="modal-label">Item notes<textarea id="oiNotes" placeholder="e.g. no onions, extra spicy"></textarea></label></div><div class="app-modal-actions"><button class="secondary modal-cancel">Cancel</button><button class="modal-confirm">Add to Order</button></div></div>';document.body.appendChild(overlay);const close=()=>overlay.remove();overlay.querySelector('.app-modal-x').onclick=close;overlay.querySelector('.modal-cancel').onclick=close;overlay.querySelector('.modal-confirm').onclick=async()=>{const modifierIds=[...overlay.querySelectorAll('.oi-mod:checked')].map(x=>Number(x.value));for(const g of groups){const count=modifierIds.filter(id=>g.modifiers.some(m=>Number(m.id)===id)).length;if(g.required&&count<Number(g.min_select||1))return showToast('Complete required '+g.name+' selection','warning');if(count>Number(g.max_select||1))return showToast('Too many '+g.name+' selections','warning')}await api('/restaurant/orders/'+currentRestaurantOrder.order.id+'/items',{method:'POST',body:JSON.stringify({productId,qty:Number(overlay.querySelector('#oiQty').value),variantId:Number(overlay.querySelector('#oiVariant')?.value)||null,modifierIds,notes:overlay.querySelector('#oiNotes').value})});close();showToast('Item added');openRestaurantOrder(currentRestaurantOrder.order.id)}}
async function editOrderItemQty(orderId,itemId,currentQty){const r=await appPrompt({title:'Change Item Quantity',message:'Current quantity: '+currentQty,placeholder:'Enter new quantity',required:true,confirmText:'Update'});if(!r)return;const qty=Number(r.comment);if(!(qty>0))return showToast('Enter a positive quantity','warning');await api('/restaurant/orders/'+orderId+'/items/'+itemId,{method:'PUT',body:JSON.stringify({qty})});openRestaurantOrder(orderId)}
async function removeRestaurantOrderItem(orderId,itemId){if(!confirm('Remove this item from the open order?'))return;await api('/restaurant/orders/'+orderId+'/items/'+itemId,{method:'DELETE'});showToast('Item removed');openRestaurantOrder(orderId)}
async function holdRestaurantOrder(id){await api('/restaurant/orders/'+id+'/hold',{method:'POST',body:'{}'});showToast('Order held');orders()}
async function resumeRestaurantOrder(id){await api('/restaurant/orders/'+id+'/resume',{method:'POST',body:'{}'});showToast('Order resumed');openRestaurantOrder(id)}
async function transitionRestaurantOrder(id,status){const labels={sent_to_kitchen:'Send order to kitchen?',preparing:'Start preparing this order?',ready:'Mark order ready?',served:'Mark order served?',bill_requested:'Request bill?',partially_paid:'Mark partially paid?',paid:'Mark order paid?',closed:'Close this order?'};const r=await appPrompt({title:'Update Order Status',message:labels[status]||status,placeholder:'Optional comment',confirmText:'Continue'});if(!r)return;await api('/restaurant/orders/'+id+'/transition',{method:'POST',body:JSON.stringify({status,comment:r.comment})});showToast('Order status updated');status==='closed'?orders():openRestaurantOrder(id)}
async function transferRestaurantOrder(id){const tables=(await api('/restaurant/tables')).filter(t=>['available','reserved'].includes(t.status));const overlay=document.createElement('div');overlay.className='app-modal-overlay';overlay.innerHTML='<div class="app-modal"><div class="app-modal-head"><h3>Transfer Table</h3><button class="app-modal-x">×</button></div><div class="app-modal-body"><label class="modal-label">Destination table<select id="transferTable">'+tables.map(t=>'<option value="'+t.id+'">'+esc(t.area_name||'')+' · '+esc(t.name)+'</option>').join('')+'</select></label><label class="modal-label">Note<textarea id="transferNote"></textarea></label></div><div class="app-modal-actions"><button class="secondary modal-cancel">Cancel</button><button class="modal-confirm">Transfer</button></div></div>';document.body.appendChild(overlay);const close=()=>overlay.remove();overlay.querySelector('.app-modal-x').onclick=close;overlay.querySelector('.modal-cancel').onclick=close;overlay.querySelector('.modal-confirm').onclick=async()=>{await api('/restaurant/orders/'+id+'/transfer',{method:'POST',body:JSON.stringify({toTableId:Number(overlay.querySelector('#transferTable').value),notes:overlay.querySelector('#transferNote').value})});close();showToast('Order transferred');openRestaurantOrder(id)}}
async function mergeRestaurantOrder(id){const rows=(await api('/restaurant/orders?status=active')).filter(o=>Number(o.id)!==Number(id));if(!rows.length)return showToast('No other open order to merge','warning');const overlay=document.createElement('div');overlay.className='app-modal-overlay';overlay.innerHTML='<div class="app-modal"><div class="app-modal-head"><h3>Merge Orders</h3><button class="app-modal-x">×</button></div><div class="app-modal-body"><label class="modal-label">Merge this order into current order<select id="mergeOrder">'+rows.map(o=>'<option value="'+o.id+'">'+esc(o.order_no)+(o.table_name?' · '+esc(o.table_name):'')+' · '+money(o.total)+'</option>').join('')+'</select></label></div><div class="app-modal-actions"><button class="secondary modal-cancel">Cancel</button><button class="modal-confirm">Merge</button></div></div>';document.body.appendChild(overlay);const close=()=>overlay.remove();overlay.querySelector('.app-modal-x').onclick=close;overlay.querySelector('.modal-cancel').onclick=close;overlay.querySelector('.modal-confirm').onclick=async()=>{await api('/restaurant/orders/'+id+'/merge',{method:'POST',body:JSON.stringify({sourceOrderId:Number(overlay.querySelector('#mergeOrder').value)})});close();showToast('Orders merged');openRestaurantOrder(id)}}
async function splitRestaurantOrder(id){const d=await api('/restaurant/orders/'+id);if(!d.items.length)return;const overlay=document.createElement('div');overlay.className='app-modal-overlay';overlay.innerHTML='<div class="app-modal"><div class="app-modal-head"><div><h3>Split Order</h3><p>Select quantities to move to a new order.</p></div><button class="app-modal-x">×</button></div><div class="app-modal-body">'+d.items.map(x=>'<label class="split-line"><span>'+esc(x.product_name)+' · '+Number(x.qty)+'</span><input class="split-qty" data-id="'+x.id+'" type="number" min="0" max="'+Number(x.qty)+'" step="0.001" value="0"></label>').join('')+'</div><div class="app-modal-actions"><button class="secondary modal-cancel">Cancel</button><button class="modal-confirm">Create Split Order</button></div></div>';document.body.appendChild(overlay);const close=()=>overlay.remove();overlay.querySelector('.app-modal-x').onclick=close;overlay.querySelector('.modal-cancel').onclick=close;overlay.querySelector('.modal-confirm').onclick=async()=>{const items=[...overlay.querySelectorAll('.split-qty')].map(x=>({itemId:Number(x.dataset.id),qty:Number(x.value)})).filter(x=>x.qty>0);if(!items.length)return showToast('Select at least one quantity','warning');const r=await api('/restaurant/orders/'+id+'/split',{method:'POST',body:JSON.stringify({items})});close();showToast('Order split created');openRestaurantOrder(Number(r.newOrder.id))}}

async function requestRestaurantOrderCancel(id){const r=await appPrompt({title:'Request Order Cancellation',message:'Cancellation will not happen until management approves it.',placeholder:'Reason for cancellation',required:true,urgent:true,confirmText:'Submit Cancellation Request',danger:true});if(!r)return;await api('/restaurant/orders/'+id+'/request-cancel',{method:'POST',body:JSON.stringify({comment:r.comment,urgent:r.urgent})});showToast(r.urgent?'Urgent cancellation request submitted':'Cancellation request submitted','warning');openRestaurantOrder(id)}
async function cancelledRestaurantOrders(){const rows=await api('/restaurant/orders?status=cancelled');$('view').innerHTML='<div class="panel"><div class="panel-head"><div><h3>Cancelled Restaurant Orders</h3><p class="muted">Management can reopen cancelled orders when appropriate.</p></div><button class="secondary" onclick="orders()">Back to Orders</button></div><div class="table-wrap"><table><thead><tr><th>Order</th><th>Type</th><th>Table</th><th>Waiter</th><th>Total</th><th>Closed</th><th></th></tr></thead><tbody>'+(rows.map(o=>'<tr><td><b>'+esc(o.order_no)+'</b></td><td>'+esc(o.order_type.replaceAll('_',' '))+'</td><td>'+esc(o.table_name||'-')+'</td><td>'+esc(o.waiter_name||'-')+'</td><td>'+money(o.total)+'</td><td>'+new Date(o.closed_at||o.updated_at).toLocaleString()+'</td><td class="right"><button class="secondary reopen-order" data-id="'+o.id+'">Reopen</button></td></tr>').join('')||'<tr><td colspan="7">No cancelled orders.</td></tr>')+'</tbody></table></div></div>';document.querySelectorAll('.reopen-order').forEach(b=>b.addEventListener('click',()=>reopenRestaurantOrder(Number(b.dataset.id))))}
async function reopenRestaurantOrder(id){const r=await appPrompt({title:'Reopen Cancelled Order',message:'Only management can reopen a cancelled order. The original table must be free.',placeholder:'Reason for reopening',required:true,confirmText:'Reopen Order'});if(!r)return;await api('/restaurant/orders/'+id+'/reopen',{method:'POST',body:JSON.stringify({comment:r.comment})});showToast('Order reopened');openRestaurantOrder(id)}

async function reservationManager(){const [rows,branches,tables,customers]=await Promise.all([api('/restaurant/reservations'),api('/branches'),api('/restaurant/tables'),api('/customers')]);const list=rows.map(r=>'<tr><td>'+new Date(r.reserved_at).toLocaleString()+'</td><td><b>'+esc(r.guest_name||r.customer_name||'Guest')+'</b><small>'+esc(r.phone||'')+'</small></td><td>'+r.guest_count+'</td><td>'+esc(r.table_name||'Unassigned')+'</td><td><span class="pill">'+esc(r.status)+'</span></td><td class="right">'+(r.status==='reserved'?'<button class="secondary res-status" data-id="'+r.id+'" data-status="cancelled">Cancel</button>':'')+'</td></tr>').join('')||'<tr><td colspan="6">No reservations.</td></tr>';$('view').innerHTML='<div class="panel"><div class="panel-head"><div><h3>Reservations</h3><p class="muted">Reserve tables and link reservations to dine-in orders.</p></div><button class="secondary" onclick="orders()">Back to Orders</button></div><div class="inline-editor"><label>Branch<select id="resBranch">'+branches.map(b=>'<option value="'+b.id+'">'+esc(b.name)+'</option>').join('')+'</select></label><label>Table<select id="resTable"><option value="">Assign later</option>'+tables.filter(t=>['available','reserved'].includes(t.status)).map(t=>'<option value="'+t.id+'">'+esc(t.area_name||'')+' · '+esc(t.name)+'</option>').join('')+'</select></label><label>Customer<select id="resCustomer"><option value="">New / walk-in guest</option>'+customers.map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join('')+'</select></label><label>Guest name<input id="resGuest"></label><label>Phone<input id="resPhone"></label><label>Covers<input id="resCount" type="number" min="1" value="2"></label><label>Date & time<input id="resAt" type="datetime-local"></label><label>Duration minutes<input id="resDuration" type="number" min="15" value="120"></label><button onclick="saveReservation()">Reserve</button></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Guest</th><th>Covers</th><th>Table</th><th>Status</th><th></th></tr></thead><tbody>'+list+'</tbody></table></div></div>';document.querySelectorAll('.res-status').forEach(b=>b.addEventListener('click',async()=>{await api('/restaurant/reservations/'+b.dataset.id+'/status',{method:'PUT',body:JSON.stringify({status:b.dataset.status})});reservationManager()}))}
async function saveReservation(){await api('/restaurant/reservations',{method:'POST',body:JSON.stringify({branchId:Number($('resBranch').value),tableId:Number($('resTable').value)||null,customerId:Number($('resCustomer').value)||null,guestName:$('resGuest').value,phone:$('resPhone').value,guestCount:Number($('resCount').value),reservedAt:$('resAt').value,durationMinutes:Number($('resDuration').value)})});showToast('Reservation created');reservationManager()}
let posProducts=[],posOrderType='counter',posCategory='all';
async function pos(){cart=[];$('view').innerHTML='<div class="pos-grid"><div class="panel"><div class="panel-head"><div><h3>New Sale</h3><p class="muted">Menu availability and pricing follow the selected order type.</p></div><select id="posOrderType"><option value="counter">Counter</option><option value="dine_in">Dine-in</option><option value="takeaway">Takeaway</option><option value="delivery">Delivery</option></select></div><input id="scan" class="scan" autofocus placeholder="Scan barcode and press Enter"><div id="posCategories" class="pos-categories"></div><div id="posProducts" class="product-grid"></div></div><div class="panel cart"><h3>Current cart</h3><div id="cartRows"></div><div class="cart-total"><span>Total</span><strong id="cartTotal">UGX 0</strong></div><select id="pay"><option value="cash">Cash</option><option value="mobile money">Mobile Money</option><option value="card">Card</option><option value="bank transfer">Bank Transfer</option><option value="credit">Credit</option></select><button class="checkout" onclick="checkout()">Complete Sale</button><div id="receiptWrap"></div></div></div>';$('posOrderType').value=posOrderType;$('posOrderType').addEventListener('change',async()=>{posOrderType=$('posOrderType').value;cart=[];renderCart();await loadPosProducts()});$('scan').addEventListener('keydown',e=>{if(e.key==='Enter'){const p=posProducts.find(x=>x.barcode===$('scan').value.trim());if(p){addCart(Number(p.id),p.name,Number(p.resolved_price));$('scan').value=''}}});await loadPosProducts();renderCart()}
async function loadPosProducts(){posProducts=await api('/menu/available?orderType='+encodeURIComponent(posOrderType));const categories=[...new Set(posProducts.map(p=>p.category_name||'Other'))];if(posCategory!=='all'&&!categories.includes(posCategory))posCategory='all';$('posCategories').innerHTML='<button class="'+(posCategory==='all'?'active':'')+'" data-cat="all">All</button>'+categories.map(c=>'<button class="'+(posCategory===c?'active':'')+'" data-cat="'+esc(c)+'">'+esc(c)+'</button>').join('');document.querySelectorAll('#posCategories [data-cat]').forEach(b=>b.addEventListener('click',()=>{posCategory=b.dataset.cat;renderPosProducts()}));renderPosProducts()}
function renderPosProducts(){const rows=posProducts.filter(p=>posCategory==='all'||(p.category_name||'Other')===posCategory);$('posProducts').innerHTML=rows.map(p=>'<button class="product-tile pos-product" data-id="'+p.id+'"><b>'+esc(p.name)+'</b><span>'+money(p.resolved_price)+'</span><small>'+esc(p.category_name||'Other')+(p.stock!=null?' · Stock '+Number(p.stock):'')+'</small></button>').join('')||'<div class="empty">No menu items are available for this order type right now.</div>';document.querySelectorAll('.pos-product').forEach(b=>b.addEventListener('click',()=>{const p=posProducts.find(x=>Number(x.id)===Number(b.dataset.id));if(p)addCart(Number(p.id),p.name,Number(p.resolved_price))}))}
function addCart(id,name,price){const x=cart.find(i=>i.productId===id);if(x)x.qty++;else cart.push({productId:id,name,price,qty:1});renderCart()}
function renderCart(){if(!$('cartRows'))return;$('cartRows').innerHTML=cart.map((x,i)=>'<div class="cart-row"><div><b>'+esc(x.name)+'</b><small>'+money(x.price)+' each</small></div><div class="qty"><button onclick="chgQty('+i+',-1)">−</button><span>'+x.qty+'</span><button onclick="chgQty('+i+',1)">+</button></div><b>'+money(x.price*x.qty)+'</b></div>').join('')||'<div class="empty">No items yet</div>';$('cartTotal').textContent=money(cart.reduce((s,x)=>s+x.price*x.qty,0))}
function chgQty(i,n){cart[i].qty+=n;if(cart[i].qty<=0)cart.splice(i,1);renderCart()}
async function checkout(){if(!cart.length)return showToast('Cart is empty','warning');const j=await api('/sales',{method:'POST',body:JSON.stringify({items:cart.map(x=>({productId:x.productId,qty:x.qty})),paymentMethod:$('pay').value,orderType:posOrderType})});$('receiptWrap').innerHTML='<div class="receipt"><h3>OWLTECH POS</h3><div>Receipt: '+esc(j.sale.receipt_no)+'</div><div>Order type: '+esc(j.sale.order_type||posOrderType)+'</div><hr>'+cart.map(x=>'<div>'+esc(x.name)+' x '+x.qty+'<span>'+money(x.price*x.qty)+'</span></div>').join('')+'<hr><h3>Total '+money(j.sale.total)+'</h3><div>Payment: '+esc(j.sale.payment_method)+'</div><button onclick="window.print()">Print 80mm Receipt</button></div>';cart=[];renderCart();await loadPosProducts();showToast('Sale completed')}
(async()=>{if(token){try{user=await api('/me');showApp()}catch{localStorage.removeItem('pos_token')}}})();